      ),
      Ayah(
        numberInSurah: 10,
        numberInQuran: 3262,
        juz: 20,
        page: 386,
        arab: "\u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0641\u064f\u0624\u064e\u0627\u062f\u064f \u0623\u064f\u0645\u0651\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0627\u0631\u0650\u063a\u064b\u0627 \u06d6 \u0625\u0650\u0646 \u0643\u064e\u0627\u062f\u064e\u062a\u0652 \u0644\u064e\u062a\u064f\u0628\u0652\u062f\u0650\u064a \u0628\u0650\u0647\u0650 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646 \u0631\u0651\u064e\u0628\u064e\u0637\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0644\u0652\u0628\u0650\u0647\u064e\u0627 \u0644\u0650\u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wa asbaha fu'aadu ummi Moosaa faarighan in kaadat latubdee bihee law laaa arrabatnaa 'alaa qalbihaa litakoona minal mu'mineen",
        translation: "Dan hati ibu Musa menjadi kosong. Sungguh, hampir saja dia menyatakannya (rahasia tentang Musa), seandainya tidak Kami teguhkan hatinya, agar dia termasuk orang-orang yang beriman (kepada janji Allah).",
        shortTafsir: "Adapun ibu Musa merasakan kerisauan yang sangat mendalam. Walaupun tindakannya menghanyutkan Musa di sungai Nil berdasarkan ilham dari Allah, namun ia sangat mengkhawatirkannya yang sangat mendalam. Hati ibu Musa menjadi kosong dan hampa. Sungguh, akibat kekhawatirannya yang sangat mendalam hampir saja dia menyatakan yakni rahasia yang dipendamnya tentang Musa. Seandainya tidak kami teguhkan hatinya pastilah dia akan meng-akui bahwa anak yang dipungut Fir\u2019aun itu adalah anak kandungnya dan dia akan berteriak meminta tolong kepada orang untuk mengambil anaknya itu kembali, yang akan mengakibatkan terbukanya rahasia bahwa Musa adalah anaknya sendiri. Peneguhan itu Kami lakukan agar dia termasuk orang-orang yang beriman yang percaya kepada janji Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3262",
      ),
      Ayah(
        numberInSurah: 11,
        numberInQuran: 3263,
        juz: 20,
        page: 386,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0644\u0650\u0623\u064f\u062e\u0652\u062a\u0650\u0647\u0650 \u0642\u064f\u0635\u0651\u0650\u064a\u0647\u0650 \u06d6 \u0641\u064e\u0628\u064e\u0635\u064f\u0631\u064e\u062a\u0652 \u0628\u0650\u0647\u0650 \u0639\u064e\u0646 \u062c\u064f\u0646\u064f\u0628\u064d \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0634\u0652\u0639\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa qaalat li ukhtihee qusseehi fabasurat bihee 'an junubinw wahum laa yash'uroon",
        translation: "Dan dia (ibunya Musa) berkata kepada saudara perempuan Musa, \u201cIkutilah dia (Musa).\u201d Maka kelihatan olehnya (Musa) dari jauh, sedang mereka tidak menyadarinya.",
        shortTafsir: "Dan setelah hatinya mulai tenang dia yakni ibunya Musa berkata kepada saudara perempuan Musa, \u201cIkutilah dan carilah berita tentang apa yang terjadi pada dia yakni Musa, dengan cara menelusuri jejak perjalanannya sejak mula dihanyutkan.\u201d Maka dia melaksanakan perintah ibunya, dan akhirnya kelihatan olehnya Musa dari jauh, sedang mereka yakni Fir\u2019aun dan tentaranya tidak menyadari bahwa ada seseorang yang memperhatikan anak yang dipungut itu dari kejauhan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3263",
      ),
      Ayah(
        numberInSurah: 12,
        numberInQuran: 3264,
        juz: 20,
        page: 386,
        arab: "\u06de \u0648\u064e\u062d\u064e\u0631\u0651\u064e\u0645\u0652\u0646\u064e\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0631\u064e\u0627\u0636\u0650\u0639\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u064f \u0641\u064e\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0647\u064e\u0644\u0652 \u0623\u064e\u062f\u064f\u0644\u0651\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0647\u0652\u0644\u0650 \u0628\u064e\u064a\u0652\u062a\u064d \u064a\u064e\u0643\u0652\u0641\u064f\u0644\u064f\u0648\u0646\u064e\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0647\u064f \u0646\u064e\u0627\u0635\u0650\u062d\u064f\u0648\u0646\u064e",
        transliteration: "Wa harramnaa 'alaihil maraadi'a min qablu faqaalat hal adullukum 'alaaa ahli baitiny yakfuloonahoo lakum wa hum lahoo naasihoon",
        translation: "Dan Kami cegah dia (Musa) menyusu kepada perempuan-perempuan yang mau menyusui(nya) sebelum itu; maka berkatalah dia (saudaranya Musa), \u201cMaukah aku tunjukkan kepadamu, keluarga yang akan memeliharanya untukmu dan mereka dapat berlaku baik padanya?\u201d",
        shortTafsir: "Allah sudah merancang cara pengembalian Musa kepangkuan ibunya tanpa diketahui semua orang. Dan kami cegah dia yakni Musa, dengan cara membuatnya enggan menyusu kepada perempuan-perempuan yang mau menyusuinya sebelum Musa dikembalikan kepada ibunya untuk disusui. Kelurga Fir\u2019aun pun merasa cemas. Maka berkatalah dia yakni saudara perempuan Musa, \u201cMaukah aku tujukkan kepadamu, keluarga yang akan memeliharanya untukmu dan mereka dapat berlaku baik padanya ? Saudara perempuan Musa menyarankan agar ia disusui oleh perempuan yang tidak lain adalah ibunya sendiri.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3264",
      ),
      Ayah(
        numberInSurah: 13,
        numberInQuran: 3265,
        juz: 20,
        page: 386,
        arab: "\u0641\u064e\u0631\u064e\u062f\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0623\u064f\u0645\u0651\u0650\u0647\u0650 \u0643\u064e\u064a\u0652 \u062a\u064e\u0642\u064e\u0631\u0651\u064e \u0639\u064e\u064a\u0652\u0646\u064f\u0647\u064e\u0627 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062d\u0652\u0632\u064e\u0646\u064e \u0648\u064e\u0644\u0650\u062a\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0623\u064e\u0646\u0651\u064e \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062d\u064e\u0642\u0651\u064c \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Faradadnaahu ilaa ummihee kai taqarra 'ainuhaa wa laa tahzana wa lita'lama anna wa'dal laahi haqqunw wa laakinna aksarahum laa ya'lamoon",
        translation: "Maka Kami kembalikan dia (Musa) kepada ibunya, agar senang hatinya dan tidak bersedih hati, dan agar dia mengetahui bahwa janji Allah adalah benar, tetapi kebanyakan mereka tidak mengetahuinya.",
        shortTafsir: "Maka setelah keluarga Fir'aun menyetujui usul agar Musa disusui oleh seseorang.yang tidak lain adalah ibunya. Kami kembalikan dia, yakni Musa kepada ibunya agar senang hatinya dengan kebersamaan sang ibu dan anaknya tanpa rasa takut atau sembunyi-sembunyi. Dan agar dia tidak bersedih hati akibat berjauhan dan kecemasannya terhadap sang anak dan agar dia mengetahui dengan seyakin-yakinnya bahwa janji Allah untuk mengembalikan Musa ke pangkuannya adalah benar sesuai dengan kenyataan. Demikianlah adanya, tetapi kebanyakan mereka yakni rezim Fir'aun dan bahkan kebanyakan manusia tidak mengetahuinya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3265",
      ),
      Ayah(
        numberInSurah: 14,
        numberInQuran: 3266,
        juz: 20,
        page: 387,
        arab: "\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0628\u064e\u0644\u064e\u063a\u064e \u0623\u064e\u0634\u064f\u062f\u0651\u064e\u0647\u064f \u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0648\u064e\u0649\u0670 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u062d\u064f\u0643\u0652\u0645\u064b\u0627 \u0648\u064e\u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u06da \u0648\u064e\u0643\u064e\u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0646\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0633\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wa lammaa balagha ashuddahoo wastawaaa aatai naahu hukmanw wa 'ilmaa; wa kazaalika najzil muhsineen",
        translation: "Dan setelah dia (Musa) dewasa dan sempurna akalnya, Kami anugerahkan kepadanya hikmah (kenabian) dan pengetahuan. Dan demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.",
        shortTafsir: "Janji Allah untuk menjadikan Musa sebagai salah seorang rasul dari kalangan bani lsrail itu benar. Dan kisahnya bermula dari setelah dia yakni Musa dewasa dan sempurna jasmani dan akalnya, Kami anugerahkan kepadanya hikmah yakni kenabian, kearifan, amal ilmiah dan pengetahuan yakni ilmu amaliah. Dan demikianlah, sebagaimana Kami telah memberi balasan kepada Musa atas ketaatannya, Kami juga akan memberi balasan kepada orang-orang yang selalu berbuat baik.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3266",
      ),
      Ayah(
        numberInSurah: 15,
        numberInQuran: 3267,
        juz: 20,
        page: 387,
        arab: "\u0648\u064e\u062f\u064e\u062e\u064e\u0644\u064e \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u062d\u0650\u064a\u0646\u0650 \u063a\u064e\u0641\u0652\u0644\u064e\u0629\u064d \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u064e\u0627 \u0641\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064e\u064a\u0652\u0646\u0650 \u064a\u064e\u0642\u0652\u062a\u064e\u062a\u0650\u0644\u064e\u0627\u0646\u0650 \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650 \u06d6 \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u064e\u0627\u062b\u064e\u0647\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646 \u0634\u0650\u064a\u0639\u064e\u062a\u0650\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0645\u0650\u0646\u0652 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u0647\u0650 \u0641\u064e\u0648\u064e\u0643\u064e\u0632\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0642\u064e\u0636\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0647\u064e\u0670\u0630\u064e\u0627 \u0645\u0650\u0646\u0652 \u0639\u064e\u0645\u064e\u0644\u0650 \u0627\u0644\u0634\u0651\u064e\u064a\u0652\u0637\u064e\u0627\u0646\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0645\u0651\u064f\u0636\u0650\u0644\u0651\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "Wa dakhalal madeenata 'alaa heene ghaflatim min ahlihaa fawajada feeha raju laini yaqtatilaani haazaa min shee'atihee wa haaza min 'aduwwihee fastaghaasahul lazee min shee'atihee 'alal lazee min 'aduwwihee fawakazahoo Moosaa faqadaa 'alaihi qaala haaza min 'amalish Shaitaani innahoo 'aduwwum mmudillum mubeen",
        translation: "Dan dia (Musa) masuk ke kota (Memphis) ketika penduduknya sedang lengah, maka dia mendapati di dalam kota itu dua orang laki-laki sedang berkelahi; yang seorang dari golongannya (Bani Israil) dan yang seorang (lagi) dari pihak musuhnya (kaum Fir\u2018aun). Orang yang dari golongannya meminta pertolongan kepadanya, untuk (mengalahkan) orang yang dari pihak musuhnya, lalu Musa meninjunya, dan matilah musuhnya itu. Dia (Musa) berkata, \u201cIni adalah perbuatan setan. Sungguh, dia (setan itu) adalah musuh yang jelas menyesatkan.\u201d",
        shortTafsir: "Dan setelah Musa dewasa dan setelah sekian lama tinggal di istana, pada suatu hari dia masuk ke kota Memphis atau Ain Syams, salah satu wilayah kekuasaan Fir'aun. Ketika itu, penduduknya sedang lengah, karena sedang istirahat sehingga jalan-jalan menjadi sepi. Lalu dia mendapati di dalam kota itu dua orang laki-laki sedang berkelahi; yang seorang dari golongannya yaitu seorang lbrani dari Bani lsrail, dan yang seorang lagi dari pihak musuhnya, yaitu bangsa Mesir kaum Fir'aun. Orang yang dari golongannya meminta pertolongan kepadanya, untuk mengalahkan orang yang dari pihak musuhnya. Memperkenankan permintaan itu Ialu Musa meninjunya, dan matilah musuhnya itu. Setelah menyadari kematian orang yang ditinjunya Dia yakni Musa, dengan sangat menyesal berkata, \"Yang kulakukan ini adalah perbuatan setan yang selalu mendorong kepada kejahatan dan kesalahan. Sungguh, dia, yakni setan itu, adalah musuh abadi manusia yang jelas menyesatkan siapa pun yang lengah.\" Musa menyesal atas kematian orang itu karena pukulannya, sebab dia bukanlah bermaksud untuk membunuhnya, tetapi hanya semata-mata membela kaumnya. lni terjadi sebelum Musa diangkat sebagai Nabi.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3267",
      ),
      Ayah(
        numberInSurah: 16,
        numberInQuran: 3268,
        juz: 20,
        page: 387,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0638\u064e\u0644\u064e\u0645\u0652\u062a\u064f \u0646\u064e\u0641\u0652\u0633\u0650\u064a \u0641\u064e\u0627\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u0650\u064a \u0641\u064e\u063a\u064e\u0641\u064e\u0631\u064e \u0644\u064e\u0647\u064f \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0647\u064f\u0648\u064e \u0627\u0644\u0652\u063a\u064e\u0641\u064f\u0648\u0631\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064f",
        transliteration: "Qaala Rabbi innee zalamtu nafsee faghfir lee faghafaralah; innahoo Huwal Ghafoorur Raheem",
        translation: "Dia (Musa) berdoa, \u201cYa Tuhanku, sesungguhnya aku telah menzalimi diriku sendiri, maka ampunilah aku.\u201d Maka Dia (Allah) mengampuninya. Sungguh, Allah, Dialah Yang Maha Pengampun, Maha Penyayang.",
        shortTafsir: "Setelah Musa menyadari kesalahannya dan menyesali perbuatannya, kini dia memohon ampunan dengan berdoa, \"Ya Tuhanku, sesungguhnya aku telah menzalimi diriku sendiri karena melakukan sesuatu yang mengakibatkan kematian seseorang, walau sebenarnya aku tidak sengaja melakukannya, dan aku sadar telah dipedaya oleh setan, maka ampunilah aku atas kesalahanku itu.\" Maka Dia yakni Allah mengampuni kesalahannya. Sungguh, itu disebabkan karena Allah bukan selain-Nya, Dialah Yang Maha Pengampun bagi siapa pun yang memohon ampunan-Nya, Maha Penyayang terhadap semua mahluk-Nya, terutama orang-orang beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3268",
      ),
      Ayah(
        numberInSurah: 17,
        numberInQuran: 3269,
        juz: 20,
        page: 387,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0652\u0639\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u0641\u064e\u0644\u064e\u0646\u0652 \u0623\u064e\u0643\u064f\u0648\u0646\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627 \u0644\u0651\u0650\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Qaala Rabbi bimaaa an'amta 'alaiya falan akoona zaheeral lilmujrimeen",
        translation: "Dia (Musa) berkata, \u201cYa Tuhanku! Demi nikmat yang telah Engkau anugerahkan kepadaku, maka aku tidak akan menjadi penolong bagi orang-orang yang berdosa.\u201d",
        shortTafsir: "Puji syukur atas segala anugerah dan nikmat Allah selama ini juga dia panjatkan dengan berkata, \"Ya Tuhanku! Demi dan disebabkan nikmat yang selama ini telah Engkau anugerahkan kepadaku sejak dalam perut ibu hingga tobat dan pengampunan-Mu ini, serta aneka nikmat lainnya, maka demi semua itu aku berjanji tidak akan menjadi penolong bagi orang-orong yang berdosa dalam melakukan perbuatan jahat,\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3269",
      ),
      Ayah(
        numberInSurah: 18,
        numberInQuran: 3270,
        juz: 20,
        page: 387,
        arab: "\u0641\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u062e\u064e\u0627\u0626\u0650\u0641\u064b\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0627\u0633\u0652\u062a\u064e\u0646\u0635\u064e\u0631\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u064a\u064e\u0633\u0652\u062a\u064e\u0635\u0652\u0631\u0650\u062e\u064f\u0647\u064f \u06da \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u063a\u064e\u0648\u0650\u064a\u0651\u064c \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064c",
        transliteration: "Fa asbaha fil madeenati khaaa'ifany yataraqqabu fa izal lazis tansarahoo bil amsi yastasrikhuh; qaala lahoo moosaaa innaka laghawiyyum mubeen",
        translation: "Karena itu, dia (Musa) menjadi ketakutan berada di kota itu sambil menunggu (akibat perbuatannya), tiba-tiba orang yang kemarin meminta pertolongan berteriak meminta pertolongan kepadanya. Musa berkata kepadanya, \u201cEngkau sungguh, orang yang nyata-nyata sesat.\u201d",
        shortTafsir: "Karena pembunuhan tak disengaja yang dilakukan oleh Musa itu, dia menjadi ketakutan berada di kota tempat terjadinya perkelahian dan pembunuhan itu sambil menunggu dengan perasaan cemas dan khawatir akibat yang akan diterima dari perbuatannya. Tiba-tiba orang lbrani yang kemarin meminta pertolongan yakni pada hari terjadinya perkelahian dan pembunuhan terhadap orang Mesir, berteriak meminta pertolongan lagi kepadanya. Akan tetapi, kali ini Musa mengecam dan menghardiknya dengan berkata, \"Engkau sungguh, orang yang nyata-nyata sesat.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3270",
      ),
      Ayah(
        numberInSurah: 19,
        numberInQuran: 3271,
        juz: 20,
        page: 387,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u0646\u0652 \u0623\u064e\u0631\u064e\u0627\u062f\u064e \u0623\u064e\u0646 \u064a\u064e\u0628\u0652\u0637\u0650\u0634\u064e \u0628\u0650\u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0647\u064f\u0648\u064e \u0639\u064e\u062f\u064f\u0648\u0651\u064c \u0644\u0651\u064e\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064e\u0646\u0650\u064a \u0643\u064e\u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064e \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u06d6 \u0625\u0650\u0646 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u062c\u064e\u0628\u0651\u064e\u0627\u0631\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0645\u064e\u0627 \u062a\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0635\u0652\u0644\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Falammaaa an araada ai yabtisha billazee huwa 'aduwwul lahumaa qaala yaa Moosaaa atureedu an taqtulanee kamaa qatalta nafsam bil amsi in tureedu illaaa an takoona jabbaaram fil ardi wa maa tureedu an takoona minal musliheen",
        translation: "Maka ketika dia (Musa) hendak memukul dengan keras orang yang menjadi musuh mereka berdua, dia (musuhnya) berkata, \u201cWahai Musa! Apakah engkau bermaksud membunuhku, sebagaimana kemarin engkau membunuh seseorang? Engkau hanya bermaksud menjadi orang yang berbuat sewenang-wenang di negeri (ini), dan engkau tidak bermaksud menjadi salah seorang dari orang-orang yang mengadakan perdamaian.\u201d",
        shortTafsir: "Kecaman itu tidak menghalangi Nabi Musa untuk menyambut permintaan pertolongan tersebut, sebab dia yakin bahwa memang orang Mesir itu yang berlaku sewenang-wenang. Maka ketika Musa bersiap hendak memukul dengan keras orang yang menjadi musuh mereka berdua, musuhnya yang orang Mesir berkata, \"Wahai Musa! Apakah engkau bermaksud membunuhku, sebagaimana kemarin engkau membunuh seseorang? Engkau hanya bermaksud menjadi orang yang berbuat sewenang-wenang yang memaksakan pendapatmu di negeri ini, dan engkau tidak bermaksud menjadi salah seorang dari kelompok orang-orang yang mengadakan perdamaian dan perbaikan untuk masyarakat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3271",
      ),
      Ayah(
        numberInSurah: 20,
        numberInQuran: 3272,
        juz: 20,
        page: 387,
        arab: "\u0648\u064e\u062c\u064e\u0627\u0621\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u0642\u0652\u0635\u064e\u0649 \u0627\u0644\u0652\u0645\u064e\u062f\u0650\u064a\u0646\u064e\u0629\u0650 \u064a\u064e\u0633\u0652\u0639\u064e\u0649\u0670 \u0642\u064e\u0627\u0644\u064e \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064e \u064a\u064e\u0623\u0652\u062a\u064e\u0645\u0650\u0631\u064f\u0648\u0646\u064e \u0628\u0650\u0643\u064e \u0644\u0650\u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0643\u064e \u0641\u064e\u0627\u062e\u0652\u0631\u064f\u062c\u0652 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0635\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Wa jaaa'a rajulum min aqsal madeenati yas'aa qaala yaa Moosaaa innal mala a yaa tamiroona bika liyaqtulooka fakhruj innee laka minan naasiheen",
        translation: "Dan seorang laki-laki datang bergegas dari ujung kota seraya berkata, \u201cWahai Musa! Sesungguhnya para pembesar negeri sedang berunding tentang engkau untuk membunuhmu, maka keluarlah (dari kota ini), sesungguhnya aku termasuk orang-orang yang memberi nasihat kepadamu.\u201d",
        shortTafsir: "Peristiwa itu menyebar ke seluruh negeri Mesir, sampai ke telinga penguasa, sehingga mereka berencana mengambil tindakan terhadap Musa Dan yang terjadi setelah itu, seorang laki-laki yang bersimpati kepada Musa, konon ia adalah seorang keluarga Fir'aun yang beriman, datang bergegas bagaikan berlari dari ujung kota seraya berkata ketika bertemu Musa, \"Wahai Musa! Sesungguhnya para pembesar dan penguasa negeri ini sedang berunding tentang engkau dan mengatur rencana buruk untuk membunuhmu, maka oleh sebab itu keluarlah dari kota ini, sesungguhnya aku termasuk orang-orang yang tulus dalam memberi nasihat kepadamu\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3272",
      ),
      Ayah(
        numberInSurah: 21,
        numberInQuran: 3273,
        juz: 20,
        page: 387,
        arab: "\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u062e\u064e\u0627\u0626\u0650\u0641\u064b\u0627 \u064a\u064e\u062a\u064e\u0631\u064e\u0642\u0651\u064e\u0628\u064f \u06d6 \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0646\u064e\u062c\u0651\u0650\u0646\u0650\u064a \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fakharaja minhaa khaaa 'ifany-yataraqqab; qaala Rabbi najjinee minal qawmiz zaalimeen",
        translation: "Maka keluarlah dia (Musa) dari kota itu dengan rasa takut, waspada (kalau ada yang menyusul atau menangkapnya), dia berdoa, \u201cYa Tuhanku, selamatkanlah aku dari orang-orang yang zalim itu.\u201d",
        shortTafsir: "Nasihat itu didengar oleh Musa, maka menuruti nasihat itu keluarlah dia dari kota itu dengan rasa takut, waspada sambil menoleh ke kanan dan ke kiri kalau-kalau ada yang menyusul atau menangkapnya. Pada saat yang sama dia berdoa \u201cYaTuhanku Yang selama ini membimbing dan memeliharaku, selamatkanlah aku dari orang-orang yang zalim semacam Fir'aun dan rezimnya itu.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3273",
      ),
      Ayah(
        numberInSurah: 22,
        numberInQuran: 3274,
        juz: 20,
        page: 388,
        arab: "\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062a\u064e\u0648\u064e\u062c\u0651\u064e\u0647\u064e \u062a\u0650\u0644\u0652\u0642\u064e\u0627\u0621\u064e \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0646 \u064a\u064e\u0647\u0652\u062f\u0650\u064a\u064e\u0646\u0650\u064a \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650",
        transliteration: "Wa lammaa tawajjaha tilqaaa'a Madyana qaala 'asaa Rabbeee ai yahdiyanee Sawaaa'as Sabeel",
        translation: "Dan ketika dia menuju ke arah negeri Madyan dia berdoa lagi, \u201cMudah-mudahan Tuhanku memimpin aku ke jalan yang benar.\u201d",
        shortTafsir: "Allah menerima doanya, dan mengarahkannya pergi ke tempat yang aman dari kejaran Fir'aun dan tentaranya. Maka pergilah dia, dan ketika dia menuju ke arah negeri Madyan dia berdoa lagi, \"Mudah-mudahan Tuhanku memimpin aku ke jalan yang benar agar aku segera sampai di tempat yang aman dengan baik dan selamat.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3274",
      ),
      Ayah(
        numberInSurah: 23,
        numberInQuran: 3275,
        juz: 20,
        page: 388,
        arab: "\u0648\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0648\u064e\u0631\u064e\u062f\u064e \u0645\u064e\u0627\u0621\u064e \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u0648\u064e\u062c\u064e\u062f\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064b \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u064a\u064e\u0633\u0652\u0642\u064f\u0648\u0646\u064e \u0648\u064e\u0648\u064e\u062c\u064e\u062f\u064e \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650\u0647\u0650\u0645\u064f \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u062a\u064e\u0630\u064f\u0648\u062f\u064e\u0627\u0646\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0645\u064e\u0627 \u062e\u064e\u0637\u0652\u0628\u064f\u0643\u064f\u0645\u064e\u0627 \u06d6 \u0642\u064e\u0627\u0644\u064e\u062a\u064e\u0627 \u0644\u064e\u0627 \u0646\u064e\u0633\u0652\u0642\u0650\u064a \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064f\u0635\u0652\u062f\u0650\u0631\u064e \u0627\u0644\u0631\u0651\u0650\u0639\u064e\u0627\u0621\u064f \u06d6 \u0648\u064e\u0623\u064e\u0628\u064f\u0648\u0646\u064e\u0627 \u0634\u064e\u064a\u0652\u062e\u064c \u0643\u064e\u0628\u0650\u064a\u0631\u064c",
        transliteration: "Wa lammaa warada maaa'a Madyana wajada 'alaihi ummatam minannaasi yasqoona wa wajada min doonihimum ra ataini tazoodaani qaala maa khatubkumaa qaalataa laa nasqee hataa yusdirar ri'aaa'u wa aboonaa shaikhun kabeer",
        translation: "Dan ketika dia sampai di sumber air negeri Madyan, dia menjumpai di sana sekumpulan orang yang sedang memberi minum (ternaknya), dan dia menjumpai di belakang orang banyak itu, dua orang perempuan sedang menghambat (ternaknya). Dia (Musa) berkata, \u201cApakah maksudmu (dengan berbuat begitu)?\u201d Kedua (perempuan) itu menjawab, \u201cKami tidak dapat memberi minum (ternak kami), sebelum penggembala-penggembala itu memulangkan (ternaknya), sedang ayah kami adalah orang tua yang telah lanjut usianya.\u201d",
        shortTafsir: "Dan ketika sudah berjalan cukup lama dan jauh, Musa sampai di sumber air negeri Madyan, dia menjumpai di sana sekumpulan orang banyak yang sedang memberi minum ternak mereka, dan dia menjumpai di belakang orang banyak itu yakni di tempat yang agak jauh dari sekumpulan orang itu, dua orang perempuan sedang menghambat ternaknya, menggiring kambing gembalaannya bergerak menjauhi sumber air, sehingga tidak ikut minum bersama dengan ternak-ternak lain. Melihat keadaan kedua perempuan itu dia yakni Musa dengan rasa iba dan heran berkata, \"Apakah maksudmu dengan berbuat begitu menghambat ternakmu minum ?\" Kedua perempuan itu menjawab pertanyaan Musa sekaligus mengisyaratkan kebutuhan mereka akan pertolongan, Kami tidak dapat memberi minum ternak kami, sebelum penggembala-penggembala itu memulangkan ternak mereka. Kami perempuan yang lemah, tidak bisa berdesak-desakan dengan laki-laki dan tidak memiliki saudara pria, sedang ayah kami adalah orang tua yang telah lanjut usianya, tidak mampu melakukan pekerjaan ini.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3275",
      ),
      Ayah(
        numberInSurah: 24,
        numberInQuran: 3276,
        juz: 20,
        page: 388,
        arab: "\u0641\u064e\u0633\u064e\u0642\u064e\u0649\u0670 \u0644\u064e\u0647\u064f\u0645\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u062a\u064e\u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0638\u0651\u0650\u0644\u0651\u0650 \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0645\u064e\u0627 \u0623\u064e\u0646\u0632\u064e\u0644\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0651\u064e \u0645\u0650\u0646\u0652 \u062e\u064e\u064a\u0652\u0631\u064d \u0641\u064e\u0642\u0650\u064a\u0631\u064c",
        transliteration: "Fasaqaa lahumaa summa tawallaaa ilaz zilli faqaala Rabbi innee limaaa anzalta ilaiya min khairin faqeer",
        translation: "Maka dia (Musa) memberi minum (ternak) kedua perempuan itu, kemudian dia kembali ke tempat yang teduh lalu berdoa, \u201cYa Tuhanku, sesungguhnya aku sangat memerlukan sesuatu kebaikan (makanan) yang Engkau turunkan kepadaku.\u201d",
        shortTafsir: "Mendengar jawaban kedua perempuan itu, maka dia yakni Musa bergegas menolong keduanya dengan memberi minum ternak kedua perempuan itu, walaupun saat itu dia sangat lapar sekali. Kedua perempuan itu meninggalkan tempat sambil mengucapkan terima kasih, kemudian Musa kembali ke tempat yang teduh untuk menghindari sengatan matahari dan beristirahat. Di tempat itu Musa mencoba mengingat kembali aneka nikmat yang telah dianugerahkan kepada-nya, lalu berdoa,\u201cYa Tuhanku, sesungguhnya aku sangat memerlukan sesuatu kebaikan berupa makanan atau rezeki lainnya, walau sedikit, yang Engkau turunkan kepadaku, Dan kini aku masih membutuhkan anugerah kebaikan darimu.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3276",
      ),
      Ayah(
        numberInSurah: 25,
        numberInQuran: 3277,
        juz: 20,
        page: 388,
        arab: "\u0641\u064e\u062c\u064e\u0627\u0621\u064e\u062a\u0652\u0647\u064f \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u062a\u064e\u0645\u0652\u0634\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0627\u0633\u0652\u062a\u0650\u062d\u0652\u064a\u064e\u0627\u0621\u064d \u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u0646\u0651\u064e \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0643\u064e \u0644\u0650\u064a\u064e\u062c\u0652\u0632\u0650\u064a\u064e\u0643\u064e \u0623\u064e\u062c\u0652\u0631\u064e \u0645\u064e\u0627 \u0633\u064e\u0642\u064e\u064a\u0652\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u06da \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f \u0648\u064e\u0642\u064e\u0635\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0635\u064e\u0635\u064e \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0646\u064e\u062c\u064e\u0648\u0652\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fajaaa'at hu ihdaahumaa tamshee 'alas tihyaaa'in qaalat inna abee yad'ooka li yajziyaka ajra maa saqaita lanaa; falammaa jaaa'ahoo wa qassa 'alaihil qasasa qaala laa takhaf najawta minal qawmiz zaalimeen",
        translation: "Kemudian datanglah kepada Musa salah seorang dari kedua perempuan itu berjalan dengan malu-malu, dia berkata, \u201cSesungguhnya ayahku mengundangmu untuk memberi balasan sebagai imbalan atas (kebaikan)mu memberi minum (ternak) kami.\u201d Ketika (Musa) mendatangi ayahnya  dan dia menceritakan kepadanya kisah (mengenai dirinya), dia berkata, \u201cJanganlah engkau takut! Engkau telah selamat dari orang-orang yang zalim itu.\u201d",
        shortTafsir: "Kedua perempuan yang dibantu oleh Musa menceritakan kebaikan Musa kepada ayah mereka. Sang Ayah memerintahkan salah seorang dari putrinya untuk mengundang Musa ke rumah. Kemudian datanglah kepada Musa salah seorang dari kedua perempuan yang baru saja ia bantu itu. Ia datang dalam keadan berjalan dengan malu-malu karena ditugaskan bertemu muka seorang diri dengan pemuda tampan dan berwibawa yang telah membantunya untuk mengundangnya ke rumah. Menyampaikan pesan sang ayah, dia berkata, \"sesungguhnya ayahku mengundangmu untuk memberi balasan sebagai imbalan atas kebaikan-mu memberi minum ternak kami. Ketika Musa mendatangi dan menemui ayah perempuan itu dirumahnya, dengan segera Musa yang sedang memerlukan bantuan menceritakan kepadanya kisah dirinya, Fir'aun dan masyarakat Mesir. Ayah perempuan itu berkata, \"Janganlah engkau takut. Kekuasaan Fir'aun tidak sampai ke wilayah ini, dan Tuhan tidak akan mencelakakan orang-orang yang selalu berbuat baik dan dekat dengan-Nya. Tenanglah, engkau telah selamat dari orang-orang yang zalim itu.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3277",
      ),
      Ayah(
        numberInSurah: 26,
        numberInQuran: 3278,
        juz: 20,
        page: 388,
        arab: "\u0642\u064e\u0627\u0644\u064e\u062a\u0652 \u0625\u0650\u062d\u0652\u062f\u064e\u0627\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0627 \u0623\u064e\u0628\u064e\u062a\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u062c\u0650\u0631\u0652\u0647\u064f \u06d6 \u0625\u0650\u0646\u0651\u064e \u062e\u064e\u064a\u0652\u0631\u064e \u0645\u064e\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0623\u0652\u062c\u064e\u0631\u0652\u062a\u064e \u0627\u0644\u0652\u0642\u064e\u0648\u0650\u064a\u0651\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0650\u064a\u0646\u064f",
        transliteration: "Qaalat ihdaahumaa yaaa abatis taajirhu inna khaira manistaajartal qawiyyul ameen",
        translation: "Dan salah seorang dari kedua (perempuan) itu berkata, \u201cWahai ayahku! Jadikanlah dia sebagai pekerja (pada kita), sesungguhnya orang yang paling baik yang engkau ambil sebagai pekerja (pada kita) ialah orang yang kuat dan dapat dipercaya.\u201d",
        shortTafsir: "Anak perempuan orang tua itu kagum kepada Musa, melihat kekuatan fisiknya dan kewibawaannya ketika mengambil air minum ternak, serta kesantunannya ketika berjalan menuju rumah. Selanjutnya salah seorang dari kedua perempuan yang datang mengundang Musa berkata, \"Wahai ayahku! Jadikanlah dia sebagai pekerja pada kita antara lain menggembalakan ternak kita, karena sesungguhnya dia adalah orang yang kuat dan terpercaya, dan sesungguhnya orang yang paling baik yang engkau ambil sebagai pekerja pada kita untuk pekerjaan apa pun ialah orang yang kuat fisik dan mentalnya dan dapat dipercaya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3278",
      ),
      Ayah(
        numberInSurah: 27,
        numberInQuran: 3279,
        juz: 20,
        page: 388,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0623\u064f\u0646\u0643\u0650\u062d\u064e\u0643\u064e \u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u0627\u0628\u0652\u0646\u064e\u062a\u064e\u064a\u0651\u064e \u0647\u064e\u0627\u062a\u064e\u064a\u0652\u0646\u0650 \u0639\u064e\u0644\u064e\u0649\u0670 \u0623\u064e\u0646 \u062a\u064e\u0623\u0652\u062c\u064f\u0631\u064e\u0646\u0650\u064a \u062b\u064e\u0645\u064e\u0627\u0646\u0650\u064a\u064e \u062d\u0650\u062c\u064e\u062c\u064d \u06d6 \u0641\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u062a\u0652\u0645\u064e\u0645\u0652\u062a\u064e \u0639\u064e\u0634\u0652\u0631\u064b\u0627 \u0641\u064e\u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u062f\u0650\u0643\u064e \u06d6 \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0631\u0650\u064a\u062f\u064f \u0623\u064e\u0646\u0652 \u0623\u064e\u0634\u064f\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u06da \u0633\u064e\u062a\u064e\u062c\u0650\u062f\u064f\u0646\u0650\u064a \u0625\u0650\u0646 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Qaala innee ureedu an unkihaka ihdab nataiya haataini 'alaaa an taajuranee samaaniya hijaj; fa in atmamta 'ashran famin 'indika wa maaa ureedu an ashuqqa 'alaik; satajiduneee in shaaa'al laahu minas saaliheen",
        translation: "Dia (Syekh Madyan) berkata, \u201cSesungguhnya aku bermaksud ingin menikahkan engkau dengan salah seorang dari kedua anak perempuanku ini, dengan ketentuan bahwa engkau bekerja padaku selama delapan tahun dan jika engkau sempurnakan sepuluh tahun maka itu adalah (suatu kebaikan) darimu, dan aku tidak bermaksud memberatkan engkau. Insya Allah engkau akan mendapatiku termasuk orang yang baik.\u201d",
        shortTafsir: "Sang ayah memahami kekaguman anak perempuannya terhadap Musa dan memang orang seperti Musalah yang didambakan setiap perempuan untuk menjadi suami. Dengan tanpa segan dia berkata, \"sesungguhnya aku bermaksud ingin menikahkan engkau dengan salah seorang dari kedua anak perempuanku ini yang telah engkau lihat dan kenal sejak di tempat sumber air. Pernikahan itu dengan ketentuan bahwa engkau bekerja padaku selama delapan tahun dan jika engkau sempurnakan yang delapan tahun itu menjadi sepuluh tahun secara sukarela maka itu adalah suatu kebaikan darimu, bukan sebuah kewajiban yang mengikat. Dan kendati itu adalah usulan dariku tetapi ketahuilah bahwa aku tidak bermaksud memberatkan engkau. Aku akan selalu berusaha menjadi orang yang menepati janji. lnsya Allah engkau akan mendapatiku termasuk orang yang baik.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3279",
      ),
      Ayah(
        numberInSurah: 28,
        numberInQuran: 3280,
        juz: 20,
        page: 388,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0628\u064e\u064a\u0652\u0646\u0650\u064a \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064e \u06d6 \u0623\u064e\u064a\u0651\u064e\u0645\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u062c\u064e\u0644\u064e\u064a\u0652\u0646\u0650 \u0642\u064e\u0636\u064e\u064a\u0652\u062a\u064f \u0641\u064e\u0644\u064e\u0627 \u0639\u064f\u062f\u0652\u0648\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0651\u064e \u06d6 \u0648\u064e\u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0645\u064e\u0627 \u0646\u064e\u0642\u064f\u0648\u0644\u064f \u0648\u064e\u0643\u0650\u064a\u0644\u064c",
        transliteration: "Qaala zaalika bainee wa bainaka aiyamal ajalaini qadaitu falaa 'udwaana 'alaiya wallaahu 'alaa ma naqoolu Wakeel",
        translation: "Dia (Musa) berkata, \u201cItu (perjanjian) antara aku dan engkau. Yang mana saja dari kedua waktu yang ditentukan itu yang aku sempurnakan, maka tidak ada tuntutan (tambahan) atas diriku (lagi). Dan Allah menjadi saksi atas apa yang kita ucapkan.\u201d",
        shortTafsir: "Setelah mempertimbangkan segala sesuatunya, Musa menerima usulan tersebut, dan dia berkata, \"Itu adalah perjanjian yang adil antara aku dan engkau. Adapun alternatif waktu yang engkau berikan, aku belum bisa memastikannya sekarang, tetapi pada prinsipnya yang mana saja dari kedua waktu yang ditentukan itu yang aku sempurnakan, maka setelah itu tidak ada tuntutan tambahan atas diriku lagi. Dan Allah menjadi saksi atas apa yang kita ucapkan.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3280",
      ),
      Ayah(
        numberInSurah: 29,
        numberInQuran: 3281,
        juz: 20,
        page: 389,
        arab: "\u06de \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0642\u064e\u0636\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u062c\u064e\u0644\u064e \u0648\u064e\u0633\u064e\u0627\u0631\u064e \u0628\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0622\u0646\u064e\u0633\u064e \u0645\u0650\u0646 \u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0646\u064e\u0627\u0631\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0627\u0645\u0652\u0643\u064f\u062b\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u0650\u064a \u0622\u0646\u064e\u0633\u0652\u062a\u064f \u0646\u064e\u0627\u0631\u064b\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0622\u062a\u0650\u064a\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u062e\u064e\u0628\u064e\u0631\u064d \u0623\u064e\u0648\u0652 \u062c\u064e\u0630\u0652\u0648\u064e\u0629\u064d \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0635\u0652\u0637\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Falammmaa qadaa Moosal ajala wa saara bi ahliheee aanasa min jaanibit Toori naaran qaala li ahlihim kusooo inneee aanastu naaral la 'alleee aateekum minhaa bikhabarin aw jazwatim minan naari la 'allakum tastaloon",
        translation: "Maka ketika Musa telah menyelesaikan waktu yang ditentukan itu dan dia berangkat dengan keluarganya, dia melihat api di lereng gunung. Dia berkata kepada keluarganya, \u201cTunggulah (di sini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa suatu berita kepadamu dari (tempat) api itu atau (membawa) sepercik api, agar kamu dapat menghangatkan badan.\u201d",
        shortTafsir: "Setelah Nabi Musa menyetujui untuk menikahi salah seorang perempuan yang ditemuinya di tempat sumber air dengan syarat-syarat yang diajukan ayah perempuan itu, hiduplah ia bersama keluarganya di Madyan. Maka ketika Musa telah menyelesaikan pekerjaan sesuai waktu yang ditentukan itu, yaitu sepuluh tahun lamanya, dan ketika dia berangkat kembali menuju tempat kelahirannya di negeri Mesir bersama dengan keluarganya untuk menemui ibunya dan saudara perempuannya, di tengah perjalanan dia melihat dengan sangat jelas api di lereng gunung dari arah bukit Sinai. Ketika itu dia berkata kepada keluarganya, \u201cTunggulah di sini, jangan beranjak dari tempat ini, sesungguhnya aku melihat cahaya api di tengah kegelapan. Aku akan mendatangi api itu, mudah-mudahan aku dapat membawa suatu berita kepadamu dari tempat api itu mengenai arah jalan yang akan kita tempuh, atau membawa sepercik api, agar kamu dapat menghangatkan badan.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3281",
      ),
      Ayah(
        numberInSurah: 30,
        numberInQuran: 3282,
        juz: 20,
        page: 389,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064e\u0627 \u0646\u064f\u0648\u062f\u0650\u064a\u064e \u0645\u0650\u0646 \u0634\u064e\u0627\u0637\u0650\u0626\u0650 \u0627\u0644\u0652\u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0652\u0623\u064e\u064a\u0652\u0645\u064e\u0646\u0650 \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064f\u0642\u0652\u0639\u064e\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0628\u064e\u0627\u0631\u064e\u0643\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u062c\u064e\u0631\u064e\u0629\u0650 \u0623\u064e\u0646 \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u0646\u064e\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0631\u064e\u0628\u0651\u064f \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Falammaaa ataahaa noodiya min shaati'il waadil aimani fil buq'atil muubaarakati minash shajarati ai yaa Moosaaa inneee Anal laahu Rabbul 'aalameen",
        translation: "Maka ketika dia (Musa) sampai ke (tempat) api itu, dia diseru dari (arah) pinggir sebelah kanan lembah, dari sebatang pohon, di sebidang tanah yang diberkahi, \u201cWahai Musa! Sungguh, Aku adalah Allah, Tuhan seluruh alam!",
        shortTafsir: "Setelah berpesan kepada keluarganya, berangkatlah Nabi Musa. Maka ketika dia sampai ke tempat yang dilihatnya sebagai sumber api itu, dia diseru dari arah pinggir sebelah kanan lembah, dari sebatang pohon yang tumbuh di sebidang tanah yang diberkahi. Panggilan itu adalah, \u201cWahai Musa! Sungguh, Aku yang engkau dengar memanggilmu ini adalah Allah, tidak ada yang patut disembah selain Aku, Tuhan Pencipta, Pemelihara dan Pengawas seluruh alam!.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3282",
      ),
      Ayah(
        numberInSurah: 31,
        numberInQuran: 3283,
        juz: 20,
        page: 389,
        arab: "\u0648\u064e\u0623\u064e\u0646\u0652 \u0623\u064e\u0644\u0652\u0642\u0650 \u0639\u064e\u0635\u064e\u0627\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u0631\u064e\u0622\u0647\u064e\u0627 \u062a\u064e\u0647\u0652\u062a\u064e\u0632\u0651\u064f \u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064e\u0627 \u062c\u064e\u0627\u0646\u0651\u064c \u0648\u064e\u0644\u0651\u064e\u0649\u0670 \u0645\u064f\u062f\u0652\u0628\u0650\u0631\u064b\u0627 \u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064f\u0639\u064e\u0642\u0651\u0650\u0628\u0652 \u06da \u064a\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0623\u064e\u0642\u0652\u0628\u0650\u0644\u0652 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062e\u064e\u0641\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0622\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wa an alqi 'asaaka falam maa ra aahaa tahtazzu ka annnahaa jaaannunw wallaa mudbiranw wa lam yu'aqqib; yaa Moosaa aqbil wa laa takhaf innaka minal aamineen",
        translation: "Dan lemparkanlah tongkatmu.\u201d Maka ketika dia (Musa) melihatnya bergerak-gerak seakan-akan seekor ular yang (gesit), dia lari berbalik ke belakang tanpa menoleh. (Allah berfirman), \u201cWahai Musa! Kemarilah dan jangan takut. Sesungguhnya engkau termasuk orang yang aman.",
        shortTafsir: "Dan lemparkanlah tongkatmu supaya kamu dapat melihat sekelumit hikmah dan kekuasaan-Ku.\u201d Maka ia pun segera melemparkannya dan kemudian Allah mengubah tongkat tersebut menjadi seekor ular. Ketika Musa melihat tongkatnya bergerak-gerak seakan-akan seekor ular kecil yang gesit padahal dia seekor ular besar, dia terkejut, takut dan lari berbalik arah ke belakang tanpa menoleh. Lalu ia mendengar Allah berfirman, \u201cWahai Musa! Kemarilah dan jangan takut melihat ular itu. Singkirkanlah rasa takut yang sedang menguasai jiwamu dan tenanglah karena sesungguhnya engkau termasuk orang yang aman dari segala sesuatu yang membahayakan. Setiap rasul yang merupakan utusan Allah tidak akan merasa takut selama dia berada di sisi-Nya. Bahkan, siapa pun yang mendekatkan diri kepada Allah ia pasti akan merasa aman dan tenteram.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3283",
      ),
      Ayah(
        numberInSurah: 32,
        numberInQuran: 3284,
        juz: 20,
        page: 389,
        arab: "\u0627\u0633\u0652\u0644\u064f\u0643\u0652 \u064a\u064e\u062f\u064e\u0643\u064e \u0641\u0650\u064a \u062c\u064e\u064a\u0652\u0628\u0650\u0643\u064e \u062a\u064e\u062e\u0652\u0631\u064f\u062c\u0652 \u0628\u064e\u064a\u0652\u0636\u064e\u0627\u0621\u064e \u0645\u0650\u0646\u0652 \u063a\u064e\u064a\u0652\u0631\u0650 \u0633\u064f\u0648\u0621\u064d \u0648\u064e\u0627\u0636\u0652\u0645\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u062c\u064e\u0646\u064e\u0627\u062d\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0647\u0652\u0628\u0650 \u06d6 \u0641\u064e\u0630\u064e\u0627\u0646\u0650\u0643\u064e \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0627\u0646\u0650 \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064e \u0648\u064e\u0645\u064e\u0644\u064e\u0626\u0650\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0641\u064e\u0627\u0633\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Usluk yadaka fee jaibika takhruj baidaaa'a min ghairi sooo'inw wadmum ilaika janaahaka minar rahbi fazaanika burhaanaani mir Rabbika ilaa Fiw'awna wa mala'ih; innahum kaanoo qawman faasiqeen",
        translation: "Masukkanlah tanganmu ke leher bajumu, dia akan keluar putih (bercahaya) tanpa cacat, dan dekapkanlah kedua tanganmu ke dadamu apabila ketakutan. Itulah dua mukjizat dari Tuhanmu (yang akan engkau pertunjukkan) kepada Fir\u2018aun dan para pembesarnya. Sungguh, mereka adalah orang-orang fasik.\u201d",
        shortTafsir: "Masukkanlah tanganmu ke dalam celah terbuka yang terdapat pada leher bajumu, niscaya dia akan keluar putih bercahaya tanpa cacat atau bukan karena penyakit, dan dekapkanlah kedua tanganmu ke dadamu apabila ketakutan agar hilang rasa takut dan kembali tenang. Jangan panik ketika kamu menyaksikan tongkat itu berubah menjadi ular atau saat tanganmu berubah putih berkilau. Tongkat yang dapat berubah menjadi ular dan tangan yang bersinar itulah dua mukjizat dari Tuhanmu yang akan engkau pertunjukkan kepada Fir\u2018aun dan para pembesarnya. Sungguh, mereka adalah orang-orang fasik, yang keluar dari ketaatan kepada Allah.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3284",
      ),
      Ayah(
        numberInSurah: 33,
        numberInQuran: 3285,
        juz: 20,
        page: 389,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0628\u0651\u0650 \u0625\u0650\u0646\u0651\u0650\u064a \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u0652 \u0646\u064e\u0641\u0652\u0633\u064b\u0627 \u0641\u064e\u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0646\u0650",
        transliteration: "Qaala Rabbi innee qataltu minhum nafsan fa akhaafu ai yaqtuloon",
        translation: "Dia (Musa) berkata, \u201cYa Tuhanku, sungguh aku telah membunuh seorang dari golongan mereka, sehingga aku takut mereka akan membunuhku.",
        shortTafsir: "Masih dalam keadaan takut dan sambil memohon pertolongan Allah, Musa berkata mengingat kesalahan yang pernah dilakukannya, \u201cYa Tuhan Pemelihara-ku, sungguh aku ketika berada di Mesir sekian tahun yang lalu telah membunuh tanpa sengaja seorang dari golongan mereka, yakni penduduk negeri Mesir, sehingga aku takut mereka akan membunuhku sebagai tindak balasan. Kalau mereka membunuhku maka aku tidak bisa menyampaikan risalah-Mu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3285",
      ),
      Ayah(
        numberInSurah: 34,
        numberInQuran: 3286,
        juz: 20,
        page: 389,
        arab: "\u0648\u064e\u0623\u064e\u062e\u0650\u064a \u0647\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0647\u064f\u0648\u064e \u0623\u064e\u0641\u0652\u0635\u064e\u062d\u064f \u0645\u0650\u0646\u0651\u0650\u064a \u0644\u0650\u0633\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0623\u064e\u0631\u0652\u0633\u0650\u0644\u0652\u0647\u064f \u0645\u064e\u0639\u0650\u064a\u064e \u0631\u0650\u062f\u0652\u0621\u064b\u0627 \u064a\u064f\u0635\u064e\u062f\u0651\u0650\u0642\u064f\u0646\u0650\u064a \u06d6 \u0625\u0650\u0646\u0651\u0650\u064a \u0623\u064e\u062e\u064e\u0627\u0641\u064f \u0623\u064e\u0646 \u064a\u064f\u0643\u064e\u0630\u0651\u0650\u0628\u064f\u0648\u0646\u0650",
        transliteration: "Wa akhee Haaroonu huwa afsahu minnee lisaanan fa arsilhu ma'iya rid ai yusaddiquneee innee akhaafu ai yukazziboon",
        translation: "Dan saudaraku Harun, dia lebih fasih lidahnya daripada aku, maka utuslah dia bersamaku sebagai pembantuku untuk membenarkan (perkataan)ku; sungguh, aku takut mereka akan mendustakanku.\u201d",
        shortTafsir: "Karena itu, lindungilah aku dan mantapkanlah hatiku karena tiada perlindungan kecuali dari-Mu, dan sebagaimana Engkau ketahui ada ikatan yang membelenggu lidahku, sedangkan saudaraku, Harun, dia lebih fasih lidahnya dan lebih lancar bicaranya daripada aku, maka utuslah dia bersamaku sebagai pembantuku untuk membenarkan perkataan-ku dalam menyampaikan pesan-pesan suci dari-Mu; sungguh, aku takut mereka, Fir`aun dan kaumnya, akan mendustakanku.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3286",
      ),
      Ayah(
        numberInSurah: 35,
        numberInQuran: 3287,
        juz: 20,
        page: 389,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0646\u064e\u0634\u064f\u062f\u0651\u064f \u0639\u064e\u0636\u064f\u062f\u064e\u0643\u064e \u0628\u0650\u0623\u064e\u062e\u0650\u064a\u0643\u064e \u0648\u064e\u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0643\u064f\u0645\u064e\u0627 \u0633\u064f\u0644\u0652\u0637\u064e\u0627\u0646\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u0650\u0644\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064e\u0627 \u06da \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0623\u064e\u0646\u062a\u064f\u0645\u064e\u0627 \u0648\u064e\u0645\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e\u0643\u064f\u0645\u064e\u0627 \u0627\u0644\u0652\u063a\u064e\u0627\u0644\u0650\u0628\u064f\u0648\u0646\u064e",
        transliteration: "Qaala sanashuddu 'adudaka bi akheeka wa naj'alu lakumaa sultaanan falaa yasiloona ilaikumaa; bi Aayaatinaa antumaa wa manit taba'akumal ghaaliboon",
        translation: "Dia (Allah) berfirman, \u201cKami akan menguatkan engkau (membantumu) dengan saudaramu, dan Kami berikan kepadamu berdua kekuasaan yang besar, maka mereka tidak akan dapat mencapaimu; (berangkatlah kamu berdua) dengan membawa mukjizat Kami, kamu berdua dan orang yang mengikuti kamu yang akan menang.\u201d",
        shortTafsir: "Sebagai pernyataan dikabulkannya permohonan Nabi Musa dan untuk menenangkan hatinya, Dia Allah berfirman, \u201cKami akan menguatkan engkau, yakni membantumu dengan mengutus pula saudaramu, Nabi Harun, yang akan bertugas membantu dan memperjelas argumentasimu sesuai permintaanmu, dan selain itu Kami berikan kepadamu berdua kekuasaan yang besar berupa kekuatan dan dukungan dengan berbagai mukjizat, maka mereka tidak akan dapat mencapaimu dengan menyakitimu dan mengalahkanmu. Karena itu, berangkatlah kamu berdua melaksanakan tugas dengan membawa mukjizat yang bersumber dari Kami. Yakinlah bahwa dengan izin Allah pada akhirnya kamu berdua dan orang yang mengikuti kamu yang akan menang atas orang-orang kafir itu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3287",
      ),
      Ayah(
        numberInSurah: 36,
        numberInQuran: 3288,
        juz: 20,
        page: 390,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0648\u0633\u064e\u0649\u0670 \u0628\u0650\u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0628\u064e\u064a\u0651\u0650\u0646\u064e\u0627\u062a\u064d \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0645\u064e\u0627 \u0647\u064e\u0670\u0630\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0633\u0650\u062d\u0652\u0631\u064c \u0645\u0651\u064f\u0641\u0652\u062a\u064e\u0631\u064b\u0649 \u0648\u064e\u0645\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u064e\u0670\u0630\u064e\u0627 \u0641\u0650\u064a \u0622\u0628\u064e\u0627\u0626\u0650\u0646\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0648\u0651\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Falammaa jaaa'ahum Moosaa bi Aayaatinaa baiyinaatin qaaloo maa haazaaa illaa sihrum muftaranw wa maa sami'naa bihaazaa feee aabaaa'inal awwaleen",
        translation: "Maka ketika Musa datang kepada mereka dengan (membawa) mukjizat Kami yang nyata, mereka berkata, \u201cIni hanyalah sihir yang dibuat-buat, dan kami tidak pernah mendengar (yang seperti) ini pada nenek moyang kami dahulu.\u201d",
        shortTafsir: "Setelah mendapat wahyu, Nabi Musa bersama keluarga kembali ke Mesir dan bersama Nabi Harun berangkatlah mereka berdua menghadapi Fir`aun dan kaumnya. Maka ketika Musa datang kepada mereka, Fir\u2018aun dan pengikutnya, dengan membawa misi kenabian yang diperkuat dengan mukjizat yang bersumber dari Kami yang sangat nyata kebenarannya, mereka mengingkari apa yang mereka saksikan seraya berkata, \u201cIni tidak lain hanyalah sihir yang dibuat-buat, yakni ilusi yang memperdayai dan mengelabui mata kita, dan dia sebenarnya hanya mengada-ngada dengan menyatakan bahwa itu bersumber dari Tuhan semesta alam, dan di samping itu kami tidak pernah mendengar ajaran yang seperti ini pada nenek moyang kami dahulu hingga kini, sehingga kami tidak dapat membenarkan dan mengikuti apa yang disampaikannya itu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3288",
      ),
      Ayah(
        numberInSurah: 37,
        numberInQuran: 3289,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0646 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u062f\u0650\u0647\u0650 \u0648\u064e\u0645\u064e\u0646 \u062a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa qaala Moosaa Rabbeee a'alamu biman jaaa'a bilhudaa min 'indihee wa man takoonu lahoo 'aaqibatud daari innahoo laa yuflihuz zaalimoon",
        translation: "Dan dia (Musa) menjawab, \u201cTuhanku lebih mengetahui siapa yang (pantas) membawa petunjuk dari sisi-Nya dan siapa yang akan mendapat kesudahan (yang baik) di akhirat. Sesungguhnya orang-orang yang zalim tidak akan mendapat kemenangan.\u201d",
        shortTafsir: "Dan sebagai jawaban bagi Fir\u2018aun dan kaumnya, dia Musa menjawab, \u201cTuhan Pemelihara-ku Yang menciptakan aku dan kamu serta memberi aneka bukti kebenaran lebih mengetahui dari aku, kamu dan siapa pun tentang siapa yang pantas membawa petunjuk dari sisi-Nya dan Dia-lah yang akan menetapkan dengan adil siapa yang akan mendapat kesudahan yang baik di akhirat. Jangan berlaku zalim, sebab sesungguhnya telah menjadi ketetapan Allah bahwa orang-orang yang zalim selamanya tidak akan mendapat kemenangan.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3289",
      ),
      Ayah(
        numberInSurah: 38,
        numberInQuran: 3290,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0641\u0650\u0631\u0652\u0639\u064e\u0648\u0652\u0646\u064f \u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0623\u064f \u0645\u064e\u0627 \u0639\u064e\u0644\u0650\u0645\u0652\u062a\u064f \u0644\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064d \u063a\u064e\u064a\u0652\u0631\u0650\u064a \u0641\u064e\u0623\u064e\u0648\u0652\u0642\u0650\u062f\u0652 \u0644\u0650\u064a \u064a\u064e\u0627 \u0647\u064e\u0627\u0645\u064e\u0627\u0646\u064f \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0637\u0651\u0650\u064a\u0646\u0650 \u0641\u064e\u0627\u062c\u0652\u0639\u064e\u0644 \u0644\u0651\u0650\u064a \u0635\u064e\u0631\u0652\u062d\u064b\u0627 \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u0650\u064a \u0623\u064e\u0637\u0651\u064e\u0644\u0650\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u0670\u0647\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0648\u064e\u0625\u0650\u0646\u0651\u0650\u064a \u0644\u064e\u0623\u064e\u0638\u064f\u0646\u0651\u064f\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064e\u0627\u0630\u0650\u0628\u0650\u064a\u0646\u064e",
        transliteration: "Wa qaala Fir'awnu yaaa aiyuhal mala-u maa 'alimtu lakum min ilaahin ghairee fa awqid lee yaa Haamaanu 'alatteeni faj'al lee sarhal la'alleee attali'u ilaaa ilaahi Moosaa wa innee la azunnuhoo minal kaazibeen",
        translation: "Dan Fir\u2018aun berkata, \u201cWahai para pembesar kaumku! Aku tidak mengetahui ada Tuhan bagimu selain aku. Maka bakarlah tanah liat untukku wahai Haman (untuk membuat batu bata), kemudian buatkanlah bangunan yang tinggi untukku agar aku dapat naik melihat Tuhannya Musa, dan aku yakin bahwa dia termasuk pendusta.\u201d",
        shortTafsir: "Dan ketika tidak kuasa lagi untuk mendebat Nabi Musa, karena jelas dan kuatnya argumentasi yang disampaikan, dengan nada menyombongkan diri Fir\u2018aun berkata, \u201cWahai para pembesar kaumku! Aku tidak mengetahui ada Tuhan bagimu selain aku yang patut disembah. Guna mengetahui kebenaran atau kebohongan Musa yang menyatakan ada Tuhan Pemelihara alam raya, maka bakarlah tanah liat untukku wahai Haman untuk membuat batu bata dan bahan bangunan lainnya, kemudian buatkanlah segera bangunan dan istana yang tinggi untukku agar aku dapat naik melihat Tuhannya Musa, dan aku yakin bahwa dia termasuk pendusta dalam dakwaannya.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3290",
      ),
      Ayah(
        numberInSurah: 39,
        numberInQuran: 3291,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0628\u064e\u0631\u064e \u0647\u064f\u0648\u064e \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064f\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u0648\u064e\u0638\u064e\u0646\u0651\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wastakbara huwa wa junooduhoo fil ardi bighairil haqqi wa zannooo annahum ilainaa laa yurja'oon",
        translation: "Dan dia (Fir\u2018aun) dan bala tentaranya berlaku sombong, di bumi tanpa alasan yang benar, dan mereka mengira bahwa mereka tidak akan dikembalikan kepada Kami.",
        shortTafsir: "Sungguh apa yang diucapkan dan direncanakan oleh Fir\u2018aun adalah sesuatu yang tidak masuk akal. Ini disebabkan hatinya bejat dan dia Fir\u2018aun dan bala tentaranya berlaku sombong di bumi Mesir tanpa alasan yang benar, dan mereka dengan sikapnya itu mengira bahwa mereka tidak akan dikembalikan di akhirat nanti kepada Kami untuk mendapatkan penghitungan dan pembalasan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3291",
      ),
      Ayah(
        numberInSurah: 40,
        numberInQuran: 3292,
        juz: 20,
        page: 390,
        arab: "\u0641\u064e\u0623\u064e\u062e\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u062c\u064f\u0646\u064f\u0648\u062f\u064e\u0647\u064f \u0641\u064e\u0646\u064e\u0628\u064e\u0630\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u0652\u064a\u064e\u0645\u0651\u0650 \u06d6 \u0641\u064e\u0627\u0646\u0638\u064f\u0631\u0652 \u0643\u064e\u064a\u0652\u0641\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fa akhaznaahu wa junoo dahoo fanabaznaahum fil yammi fanzur kaifa kaana 'aaqibatuz zaalimeen",
        translation: "Maka Kami siksa dia (Fir\u2018aun) dan bala tentaranya, lalu Kami lemparkan mereka ke dalam laut. Maka perhatikanlah bagaimana kesudahan orang yang zalim.",
        shortTafsir: "Maka sebagai akibat keangkuhan dan kedurhakaan mereka dan setelah itu mencapai puncaknya Kami siksa dia, yakni Fir\u2018aun dan bala tentaranya, lalu Kami lemparkan mereka ke dalam Laut Merah seperti melempar batu-batu kecil yang tidak berarti sehingga mereka semua mati tenggelam. Maka perhatikanlah, wahai Nabi Muhammad dan siapa pun yang mengetahui peristiwa itu, bagaimana kesudahan buruk yang menimpa orang yang zalim.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3292",
      ),
      Ayah(
        numberInSurah: 41,
        numberInQuran: 3293,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0623\u064e\u0626\u0650\u0645\u0651\u064e\u0629\u064b \u064a\u064e\u062f\u0652\u0639\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u0649 \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0644\u064e\u0627 \u064a\u064f\u0646\u0635\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa ja'alnaahum a'immatany yad'oona ilan Naari wa Yawmal Qiyaamati laa yunsaroon",
        translation: "Dan Kami jadikan mereka para pemimpin yang mengajak (manusia) ke neraka dan pada hari Kiamat mereka tidak akan ditolong.",
        shortTafsir: "Dan sesuai dengan kehendak serta jati diri mereka Kami jadikan mereka para pemimpin kekufuran dan kedurhakaan yang selalu mengajak manusia yang lemah jiwa dan akalnya kepada perbuatan buruk yang menyebabkan mereka masuk ke neraka, dan dengan demikian mereka akan menjadi penghuni neraka, sehingga pada hari Kiamat mereka tidak akan ditolong, karena mereka kafir dan selalu mendustakan Rasul utusan Tuhan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3293",
      ),
      Ayah(
        numberInSurah: 42,
        numberInQuran: 3294,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u0623\u064e\u062a\u0652\u0628\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0644\u064e\u0639\u0652\u0646\u064e\u0629\u064b \u06d6 \u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0642\u0652\u0628\u064f\u0648\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Wa atba'naahum fee haazihid dunyaa la'natanw wa Yawmal Qiyaamati hum minal maqbooheen",
        translation: "Dan Kami susulkan laknat kepada mereka di dunia ini; sedangkan pada hari Kiamat mereka termasuk orang-orang yang dijauhkan (dari rahmat Allah).",
        shortTafsir: "Dan Kami susulkan laknat kepada mereka di dunia ini berupa kehinaan dan kemurkaan dari Kami; sedangkan pada hari Kiamat mereka termasuk orang-orang yang dijauhkan dari kebaikan, rahmat dan karunia Allah. Adakah siksa yang lebih pedih dari itu semua? Untuk menghindari azab tersebut, Allah memberi jalan keselamatan kepada manusia di zaman Nabi Musa, yaitu dengan berpegang teguh kepada kita suci Taurat seperti dijelaskan pada ayat berikut.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3294",
      ),
      Ayah(
        numberInSurah: 43,
        numberInQuran: 3295,
        juz: 20,
        page: 390,
        arab: "\u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646 \u0628\u064e\u0639\u0652\u062f\u0650 \u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0628\u064e\u0635\u064e\u0627\u0626\u0650\u0631\u064e \u0644\u0650\u0644\u0646\u0651\u064e\u0627\u0633\u0650 \u0648\u064e\u0647\u064f\u062f\u064b\u0649 \u0648\u064e\u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u0651\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa laqad aatainaa Moosal Kitaaba mim ba'di maaa ahlaknal quroonal oolaa basaaa'ira linnaasi wa hudanw wa rahmatal la'allahum yata zakkkaroon",
        translation: "Dan sungguh, telah Kami berikan kepada Musa Kitab (Taurat) setelah Kami binasakan umat-umat terdahulu, untuk menjadi pelita bagi manusia dan petunjuk serta rahmat, agar mereka mendapat pelajaran.",
        shortTafsir: "Kisah Bani Israil ditutup oleh ayat ini dengan menjelaskan dasar kepemimpinan Nabi Musa, setelah ayat yang lalu menjelaskan kepemimpinan Fir`aun dalam kekufuran. Sambil bersumpah Allah berfirman, dan demi keagungan dan kekuasaan Kami, sungguh, telah Kami berikan kepada Musa Kitab Taurat yang mengandung hukum dan petunjuk kebahagiaan bagi masyarakat Bani Israil, setelah Kami binasakan umat-umat terdahulu, seperti kaum Nabi Nuh, kaum Nabi Hud (`Ad), kaum Nabi Saleh (\u0160am\u00f9d), kaum Nabi Lut dan penduduk negeri Madyan. Kitab itu Kami anugerahkan untuk menjadi pelita cahaya bagi hati manusia yang sebelumnya berada dalam kegelapan dan tidak mengetahui kebenaran, dan juga agar menjadi petunjuk bagi yang memerhatikan kandungannya, serta menjadi jalan untuk mendapatkan rahmat bagi yang melaksanakannya. Semua itu Kami anugerahkan agar mereka mendapat pelajaran dari apa yang ada di dalamnya, sehingga bergegas menjalankan perintah dan menjauhi larangan, dan juga agar mereka selalu mengingat kebesaran Allah dan aneka anugerah-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3295",
      ),
      Ayah(
        numberInSurah: 44,
        numberInQuran: 3296,
        juz: 20,
        page: 391,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0652\u063a\u064e\u0631\u0652\u0628\u0650\u064a\u0651\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0636\u064e\u064a\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064f\u0648\u0633\u064e\u0649 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u064e \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0634\u0651\u064e\u0627\u0647\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Wa maa kunta bijaanibil gharbiyyi iz qadainaaa ilaa Moosal amra wa maa kunta minash shaahideen",
        translation: "Dan engkau (Muhammad) tidak berada di sebelah barat (lembah suci Tuwa) ketika Kami menyampaikan perintah kepada Musa, dan engkau tidak (pula) termasuk orang-orang yang menyaksikan (kejadian itu).",
        shortTafsir: "Setelah selesai dipaparkan kisah Nabi Musa, Allah menyampaikan kepada Nabi Muhammad tentang penegasan tentang kenabian dan kerasulannya. Dan engkau wahai Nabi Muhammad tidak bersama Nabi Musa berada di sebelah barat lembah suci Tuwa di gunung Sinai ketika Kami menyampaikan perintah kepada Musa untuk menyampaikan risalah dan menghadapi Fir`aun, dan engkau tidak pula hidup sezaman dengannya sehingga termasuk orang-orang yang menyaksikan kejadian itu. Namun demikian engkau dapat mengetahuinya secara benar, padahal engkau pun tidak pandai membaca atau pernah belajar. Ini bukti bahwa engkau mendapat wahyu dari Allah. Maka, bagaimana kaummu mendustakan risalahmu sedangkan kamu hanya membacakan kabar orang-orang terdahulu pada mereka?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3296",
      ),
      Ayah(
        numberInSurah: 45,
        numberInQuran: 3297,
        juz: 20,
        page: 391,
        arab: "\u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0623\u064e\u0646\u0634\u064e\u0623\u0652\u0646\u064e\u0627 \u0642\u064f\u0631\u064f\u0648\u0646\u064b\u0627 \u0641\u064e\u062a\u064e\u0637\u064e\u0627\u0648\u064e\u0644\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0639\u064f\u0645\u064f\u0631\u064f \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062b\u064e\u0627\u0648\u0650\u064a\u064b\u0627 \u0641\u0650\u064a \u0623\u064e\u0647\u0652\u0644\u0650 \u0645\u064e\u062f\u0652\u064a\u064e\u0646\u064e \u062a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0631\u0652\u0633\u0650\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Wa laakinnaa anshaanaa quroonan fatataawala 'alaihimul 'umur; wa maa kunta saawiyan feee ahli Madyana tatloo 'alaihim Aayaatinaa wa laakinnaa kunnaa mursileen",
        translation: "Tetapi Kami telah menciptakan beberapa umat, dan telah berlalu atas mereka masa yang panjang, dan engkau (Muhammad) tidak tinggal bersama-sama penduduk Madyan dengan membacakan ayat-ayat Kami kepada mereka, tetapi Kami telah mengutus rasul-rasul.",
        shortTafsir: "Engkau tidak mengalami peristiwa-peristiwa itu, tetapi Kami telah menciptakan beberapa umat dalam berbagai generasi setelah Nabi Musa, dan telah berlalu atas mereka masa yang panjang, sehingga mereka lupa dengan perjanjian yang telah mereka ambil dan meninggalkan perintah Allah. Kami utus engkau untuk memperbaharui kembali dakwah yang pernah disampaikan oleh nabi-nabi terdahulu. Dan demikian pula engkau wahai Nabi Muhammad tidak tinggal bersama-sama penduduk Madyan dengan membacakan ayat-ayat Kami kepada mereka, sehingga dapat memberitahu penduduk Mekah tentang kabar mereka. Engkau tidak tinggal bersama mereka di Madyan, akan tetapi Kami telah mengutus rasul-rasul dan Kami beritahukan kepadamu tentang kisah-kisah mereka melalui wahyu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3297",
      ),
      Ayah(
        numberInSurah: 46,
        numberInQuran: 3298,
        juz: 20,
        page: 391,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u0628\u0650\u062c\u064e\u0627\u0646\u0650\u0628\u0650 \u0627\u0644\u0637\u0651\u064f\u0648\u0631\u0650 \u0625\u0650\u0630\u0652 \u0646\u064e\u0627\u062f\u064e\u064a\u0652\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646 \u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0645\u0651\u064e\u0627 \u0623\u064e\u062a\u064e\u0627\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0630\u0650\u064a\u0631\u064d \u0645\u0651\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa maa kunta bijaanibit Toori iz naadainaa wa laakir rahmatam mir Rabbika litunzira qawmam maaa ataahum min nazeerim min qablika la'allahum yatazakkaroon",
        translation: "Dan engkau (Muhammad) tidak berada di dekat Tur (gunung) ketika Kami menyeru (Musa), tetapi (Kami utus engkau) sebagai rahmat dari Tuhanmu, agar engkau memberi peringatan kepada kaum (Quraisy) yang tidak didatangi oleh pemberi peringatan sebelum engkau agar mereka mendapat pelajaran.",
        shortTafsir: "Dan engkau wahai Nabi Muhammad tidak berada di dekat gunung Sinai ketika Kami menyeru Nabi Musa dan memilihnya untuk menyampaikan pesan-pesan suci. Akan tetapi Kami utus engkau sebagai rahmat dari Tuhanmu, agar engkau memberi peringatan kepada kaum masyarakat Arab yang tidak didatangi oleh pemberi peringatan dalam kurun waktu yang cukup lama sebelum engkau, agar dengan peringatanmu itu mereka mendapat pelajaran.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3298",
      ),
      Ayah(
        numberInSurah: 47,
        numberInQuran: 3299,
        juz: 20,
        page: 391,
        arab: "\u0648\u064e\u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646 \u062a\u064f\u0635\u0650\u064a\u0628\u064e\u0647\u064f\u0645 \u0645\u0651\u064f\u0635\u0650\u064a\u0628\u064e\u0629\u064c \u0628\u0650\u0645\u064e\u0627 \u0642\u064e\u062f\u0651\u064e\u0645\u064e\u062a\u0652 \u0623\u064e\u064a\u0652\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u062a\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u0641\u064e\u0646\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064e \u0622\u064a\u064e\u0627\u062a\u0650\u0643\u064e \u0648\u064e\u0646\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e",
        transliteration: "Wa law laaa an tuseebahum museebatum bimaa qaddamat aideehim fa yaqooloo Rabbanaa law laaa arsalta ilainaa Rasoolan fanattabi'a Aayaatika wa nakoona minal mu'mineen",
        translation: "Dan agar mereka tidak mengatakan ketika azab menimpa mereka disebabkan apa yang mereka kerjakan, \u201cYa Tuhan kami, mengapa Engkau tidak mengutus seorang rasul kepada kami, agar kami mengikuti ayat-ayat Engkau dan termasuk orang mukmin.\u201d",
        shortTafsir: "Dan agar mereka tidak mengatakan ketika azab menimpa mereka yang sebenarnya bukan Kami penyebabnya, tetapi disebabkan apa yang mereka kerjakan, \u201cYa Tuhan kami, mengapa Engkau tidak mengutus seorang rasul yang memberi tuntunan dan peringatan kepada kami, agar kami mengikuti ayat-ayat Engkau dan termasuk orang mukmin.\u201d Agar mereka tidak beralasan demikian, Kami utus engkau kepada mereka dan kepada alam semesta sebagai pembawa berita gembira dan peringatan dari Tuhan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3299",
      ),
      Ayah(
        numberInSurah: 48,
        numberInQuran: 3300,
        juz: 20,
        page: 391,
        arab: "\u0641\u064e\u0644\u064e\u0645\u0651\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0646\u062f\u0650\u0646\u064e\u0627 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u0652\u0641\u064f\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u064f \u06d6 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0633\u0650\u062d\u0652\u0631\u064e\u0627\u0646\u0650 \u062a\u064e\u0638\u064e\u0627\u0647\u064e\u0631\u064e\u0627 \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0628\u0650\u0643\u064f\u0644\u0651\u064d \u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Falammaa jaaa'ahumul haqqu min 'indinaa qaaloo law laa ootiya misla maaa ootiyaa Moosaa; awalam yakfuroo bimaaa ootiya Moosaa min qablu qaaloo sihraani tazaaharaa wa qaalooo innaa bikullin kaafiroon",
        translation: "Maka ketika telah datang kepada mereka kebenaran (Al-Qur'an) dari sisi Kami, mereka berkata, \u201cMengapa tidak diberikan kepadanya (Muhammad) seperti apa yang telah diberikan kepada Musa dahulu?\u201d Bukankah mereka itu telah ingkar (juga) kepada apa yang diberikan kepada Musa dahulu? Mereka dahulu berkata, \u201c(Musa dan Harun adalah) dua pesihir yang bantu-membantu.\u201d Dan mereka (juga) berkata, \u201cSesungguhnya kami sama sekali tidak mempercayai masing-masing mereka itu.\u201d",
        shortTafsir: "Maka ketika Rasulullah telah datang kepada mereka dengan membawa kebenaran yang sempurna berupa Al-Qur'an yang berasal dari sisi Kami, dengan nada ingkar mereka berkata, \u201cMengapa tidak diberikan kepadanya, yakni Nabi Muhammad, bukti kebenaran risalah dalam bentuk mukjizat inderawi dan kitab suci yang diturunkan sekaligus seperti apa yang telah diberikan kepada Musa dahulu, misalnya tongkat yang berubah menjadi ular, atau tangan yang tampak bersinar cemerlang dan lain-lain?\u201d Mereka, yakni kaum musyrik Mekah, berkata demikian padahal bukankah sebelumnya mereka itu telah ingkar juga kepada apa yang diberikan kepada Musa dahulu? Mereka dahulu berkata, \u201cNabi Musa dan Nabi Harun adalah dua pesihir yang bantu-membantu dan saling benar-membenarkan.\u201d Dan mereka juga berkata, \u201cSesungguhnya kami sama sekali tidak mempercayai masing-masing mereka itu.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3300",
      ),
      Ayah(
        numberInSurah: 49,
        numberInQuran: 3301,
        juz: 20,
        page: 391,
        arab: "\u0642\u064f\u0644\u0652 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0628\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u064d \u0645\u0651\u0650\u0646\u0652 \u0639\u0650\u0646\u062f\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0647\u064f\u0648\u064e \u0623\u064e\u0647\u0652\u062f\u064e\u0649\u0670 \u0645\u0650\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0652\u0647\u064f \u0625\u0650\u0646 \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u0635\u064e\u0627\u062f\u0650\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Qul faatoo bi Kitaabim min 'indil laahi huwa ahdaa minhu maaa attabi'hu in kuntum saadiqeen",
        translation: "Katakanlah (Muhammad), \u201cDatangkanlah olehmu sebuah kitab dari sisi Allah yang kitab itu lebih memberi petunjuk daripada keduanya (Taurat dan Al-Qur'an), niscaya aku mengikutinya, jika kamu orang yang benar.\u201d",
        shortTafsir: "Untuk menyanggah argumentasi mereka, Allah perintahkan kepada Rasul-Nya, katakanlah kepada mereka wahai Nabi Muhammad, \u201cApabila kamu tidak beriman kepada Taurat dan Al-Qur\u2019an, datangkanlah olehmu, secara sendiri-sendiri atau bersama-sama, sebuah kitab dari sisi Allah yang kitab itu lebih memberi petunjuk daripada keduanya, yakni Taurat dan Al-Qur'an, atau yang semisal dengannya, niscaya aku akan mengikutinya. Lakukanlah jika kamu memang orang yang benar dalam prasangka kamu bahwa apa yang kami datangkan itu adalah sihir.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3301",
      ),
      Ayah(
        numberInSurah: 50,
        numberInQuran: 3302,
        juz: 20,
        page: 391,
        arab: "\u0641\u064e\u0625\u0650\u0646 \u0644\u0651\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0643\u064e \u0641\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u064f\u0648\u0646\u064e \u0623\u064e\u0647\u0652\u0648\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u06da \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0636\u064e\u0644\u0651\u064f \u0645\u0650\u0645\u0651\u064e\u0646\u0650 \u0627\u062a\u0651\u064e\u0628\u064e\u0639\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u0628\u0650\u063a\u064e\u064a\u0652\u0631\u0650 \u0647\u064f\u062f\u064b\u0649 \u0645\u0651\u0650\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u06da \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Fa il lam yastajeeboo laka fa'lam annamaa yattabi'oona ahwaaa'ahum; w aman adallu mimmanit taba'a hawaahu bighari hudam minal laah; innal laaha laa yahdil qawmaz zaalimeen",
        translation: "Maka jika mereka tidak menjawab (tantanganmu), maka ketahuilah bahwa mereka hanyalah mengikuti keinginan mereka. Dan siapakah yang lebih sesat daripada orang yang mengikuti keinginannya tanpa mendapat petunjuk dari Allah sedikit pun? Sungguh, Allah tidak memberi petunjuk kepada orang-orang yang zalim.",
        shortTafsir: "Sudah barang tentu mereka tidak akan mampu mendatangkannya. Maka jika mereka tidak mampu menjawab tantanganmu untuk mendatangkan kitab berisi petunjuk yang lebih baik daripada Al-Qur`an, bahkan yang semisal dengannya, atau jika mereka tidak menyambut ajakanmu untuk beriman, maka ketahuilah wahai Nabi Muhammad atau siapa pun, bahwa mereka tidak lagi memiliki dalih atau alasan penolakan. Dan dengan begitu, jika mereka tetap menolak, maka sesungguhnya mereka hanyalah mengikuti keinginan hawa nafsu mereka tanpa alasan yang kuat dan benar, dan dengan demikian mereka pada hakikatnya tidak memperoleh petunjuk, bahkan mereka adalah orang-orang yang sesat. Dan siapakah yang lebih sesat daripada orang yang mengikuti keinginan hawa nafsu-nya tanpa mendapat petunjuk dari Allah sedikit pun dan tanpa memiliki pijakan yang logis? Pastilah tidak ada yang lebih sesat daripada mereka. Sungguh, Allah tidak memberi petunjuk kepada orang-orang yang zalim yang melampaui batas-batas yang telah ditentukan oleh Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3302",
      ),
      Ayah(
        numberInSurah: 51,
        numberInQuran: 3303,
        juz: 20,
        page: 392,
        arab: "\u06de \u0648\u064e\u0644\u064e\u0642\u064e\u062f\u0652 \u0648\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064e \u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u064a\u064e\u062a\u064e\u0630\u064e\u0643\u0651\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa laqad wassalnaa lahumul qawla la'allahum yatazakkaroon",
        translation: "Dan sungguh, Kami telah menyampaikan perkataan ini (Al-Qur'an) kepada mereka agar mereka selalu mengingatnya.",
        shortTafsir: "Dan demi keagungan dan kekuasaan Kami, sungguh, Kami telah menyampaikan perkataan ini, yaitu Al-Qur'an kepada mereka secara berkesinambungan. Sebagian turun menyusul yang lain, sesuai kebutuhan. Al-Qur'an juga diturunkan secara berturut-turut dalam bentuk janji, ancaman, kisah-kisah dan pelajaran-pelajaran, semua itu agar mereka selalu mengingatnya, merenungi dan mempercayai apa yang ada di dalam-nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3303",
      ),
      Ayah(
        numberInSurah: 52,
        numberInQuran: 3304,
        juz: 20,
        page: 392,
        arab: "\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0647\u064f\u0645 \u0628\u0650\u0647\u0650 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0646\u064e",
        transliteration: "Allazeena aatainaahu mul Kitaaba min qablihee hum bihee yu'minoon",
        translation: "Orang-orang yang telah Kami berikan kepada mereka Al-Kitab sebelum Al-Qur'an, mereka beriman (pula) kepadanya (Al-Qur'an).",
        shortTafsir: "Siapa pun yang membuka mata hati dan pikirannya menyangkut Al-Qur'an tentu dia akan beriman. Buktinya adalah orang-orang yang telah Kami berikan kepada mereka Al-Kitab, yakni Taurat dan Injil, sebelum datang Al-Qur'an, kemudian beriman kepada kitab tersebut dan membenarkan apa yang ada di dalamnya tentang Muhammad dan kitab sucinya, maka sesungguhnya mereka telah beriman pula kepadanya, yakni Muhammad dan Al-Qur'an.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3304",
      ),
      Ayah(
        numberInSurah: 53,
        numberInQuran: 3305,
        juz: 20,
        page: 392,
        arab: "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u064a\u064f\u062a\u0652\u0644\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0622\u0645\u064e\u0646\u0651\u064e\u0627 \u0628\u0650\u0647\u0650 \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064f \u0645\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0646\u064e\u0627 \u0625\u0650\u0646\u0651\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e",
        transliteration: "Wa izaa yutlaa 'alaihim qaaloo aamannaa biheee innahul haqqu mir rabbinaaa innaa kunnaa min qablihee muslimeen",
        translation: "Dan apabila (Al-Qur'an) dibacakan kepada mereka, mereka berkata, \u201cKami beriman kepadanya, sesungguhnya (Al-Qur'an) itu adalah suatu kebenaran dari Tuhan kami. Sungguh, sebelumnya kami adalah orang muslim.\u201d",
        shortTafsir: "Oleh karena itu mereka menerimanya dengan tulus, dan apabila Al-Qur'an dibacakan kepada mereka, dengan bergegas tanpa banyak berpikir mereka berkata, \u201cKami telah beriman kepadanya, karena sesungguhnya Al-Qur'an itu adalah suatu kebenaran yang sempurna dari Tuhan Pemelihara kami. Dan kami telah mengetahui Muhammad dan kitab sucinya sebelum kitab itu diturunkan. Sungguh, sebelumnya kami adalah orang muslim yang tunduk patuh dan berserah diri kepada Allah.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3305",
      ),
      Ayah(
        numberInSurah: 54,
        numberInQuran: 3306,
        juz: 20,
        page: 392,
        arab: "\u0623\u064f\u0648\u0644\u064e\u0670\u0626\u0650\u0643\u064e \u064a\u064f\u0624\u0652\u062a\u064e\u0648\u0652\u0646\u064e \u0623\u064e\u062c\u0652\u0631\u064e\u0647\u064f\u0645 \u0645\u0651\u064e\u0631\u0651\u064e\u062a\u064e\u064a\u0652\u0646\u0650 \u0628\u0650\u0645\u064e\u0627 \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u064a\u064e\u062f\u0652\u0631\u064e\u0621\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u064e \u0648\u064e\u0645\u0650\u0645\u0651\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u064a\u064f\u0646\u0641\u0650\u0642\u064f\u0648\u0646\u064e",
        transliteration: "Ulaaa'ika yu'tawna ajrahum marratayni bimaa sabaroo wa yadra'oona bil hasanatis saiyi'ata wa mimmmaa razaq naahum yunfiqoon",
        translation: "Mereka itu diberi pahala dua kali (karena beriman kepada Taurat dan Al-Qur'an) disebabkan kesabaran mereka, dan mereka menolak kejahatan dengan kebaikan, dan menginfakkan sebagian dari rezeki yang telah Kami berikan kepada mereka.",
        shortTafsir: "Orang-orang yang beriman kepada Al-Qur'an dan apa yang diturunkan sebelumnya, mereka itu sungguh tinggi kedudukannya di sisi Allah dan diberi pahala dua kali lipat karena beriman kepada Taurat dan Al-Qur'an. Hal ini disebabkan kesabaran mereka atas penderitaan yang mereka terima demi mempertahankan keimanan dan mengutamakan amal saleh. Dan di antara sifat-sifat mereka adalah mereka menolak kejahatan dengan memberi maaf, bahkan membalasnya dengan amal kebaikan, dan mereka juga adalah para dermawan yang menginfakkan sebagian dari rezeki yang telah Kami berikan kepada mereka di jalan kebaikan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3306",
      ),
      Ayah(
        numberInSurah: 55,
        numberInQuran: 3307,
        juz: 20,
        page: 392,
        arab: "\u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0633\u064e\u0645\u0650\u0639\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u063a\u0652\u0648\u064e \u0623\u064e\u0639\u0652\u0631\u064e\u0636\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064f \u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0646\u064e\u0627 \u0648\u064e\u0644\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0633\u064e\u0644\u064e\u0627\u0645\u064c \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0644\u064e\u0627 \u0646\u064e\u0628\u0652\u062a\u064e\u063a\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0627\u0647\u0650\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Wa izaa sami'ul laghwa a'radoo 'anhu wa qaaloo lanaaa a'maalunaa wa lakum a'maalukum salaamun 'alaikum laa nabtaghil jaahileen",
        translation: "Dan apabila mereka mendengar perkataan yang buruk, mereka berpaling darinya dan berkata, \u201cBagi kami amal-amal kami dan bagimu amal-amal kamu, semoga selamatlah kamu, kami tidak ingin (bergaul) dengan orang-orang bodoh.\u201d",
        shortTafsir: "Dan sifat mereka lainnya adalah apabila mereka mendengar perkataan yang buruk, yang tidak bermanfaat bagi kebaikan hidup dunia dan akhirat, mereka memelihara kehormatan diri mereka dengan berpaling darinya dan berkata, \u201cBagi kami amal-amal kami yang benar dan tidak akan kami tinggalkan dan bagimu amal-amal kamu yang batil yang dosanya akan kalian tanggung sendiri. Semoga selamatlah kamu. Selamat berpisah, kami akan membiarkan dan tidak mencampuri urusan kamu karena kami tidak ingin bergaul dengan orang-orang bodoh, yang tidak enggan berpegang teguh pada ajaran Allah.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3307",
      ),
      Ayah(
        numberInSurah: 56,
        numberInQuran: 3308,
        juz: 20,
        page: 392,
        arab: "\u0625\u0650\u0646\u0651\u064e\u0643\u064e \u0644\u064e\u0627 \u062a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u0628\u064e\u0628\u0652\u062a\u064e \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0647\u0652\u062f\u0650\u064a \u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u06da \u0648\u064e\u0647\u064f\u0648\u064e \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0627\u0644\u0652\u0645\u064f\u0647\u0652\u062a\u064e\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Innaka laa tahdee man ahbata wa laakinna laaha yahdee mai yashaaa'; wa Huwaa'lamu bilmuhtadeen",
        translation: "Sungguh, engkau (Muhammad) tidak dapat memberi petunjuk kepada orang yang engkau kasihi, tetapi Allah memberi petunjuk kepada orang yang Dia kehendaki, dan Dia lebih mengetahui orang-orang yang mau menerima  petunjuk.",
        shortTafsir: "Hidayah yang mengantar seseorang menerima dan melaksanakan tuntunan Allah bukanlah wewenang manusia, atau dalam batas kemampuannya, tetapi semata-mata wewenang dan hak prerogatif Allah. Di sini Allah menjelaskan hakikat tersebut dengan penegasan, \"Sungguh, engkau wahai Nabi Muhammad, tidak dapat memberi petunjuk dalam bentuk hidayah tauf\u00ecq yang menjadikan seseorang menerima dengan baik dan melaksanakan ajaran Allah kepada orang yang engkau kasihi, meski engkau sangat berhasrat untuk memberi petunjuk kepada kaummu. Engkau hanya mampu memberi hidayah irsy\u00e0d, dalam arti memberi petunjuk dan memberitahu tentang jalan kebahagiaan, tetapi Allah-lah yang memberi petunjuk keimanan hidayah kepada orang yang Dia kehendaki-Nya bila dia bersedia menerima hidayah dan membuka hatinya untuk itu, dan Dia lebih mengetahui orang-orang yang mau menerima petunjuk.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3308",
      ),
      Ayah(
        numberInSurah: 57,
        numberInQuran: 3309,
        juz: 20,
        page: 392,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0625\u0650\u0646 \u0646\u0651\u064e\u062a\u0651\u064e\u0628\u0650\u0639\u0650 \u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0643\u064e \u0646\u064f\u062a\u064e\u062e\u064e\u0637\u0651\u064e\u0641\u0652 \u0645\u0650\u0646\u0652 \u0623\u064e\u0631\u0652\u0636\u0650\u0646\u064e\u0627 \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u0646\u064f\u0645\u064e\u0643\u0651\u0650\u0646 \u0644\u0651\u064e\u0647\u064f\u0645\u0652 \u062d\u064e\u0631\u064e\u0645\u064b\u0627 \u0622\u0645\u0650\u0646\u064b\u0627 \u064a\u064f\u062c\u0652\u0628\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062b\u064e\u0645\u064e\u0631\u064e\u0627\u062a\u064f \u0643\u064f\u0644\u0651\u0650 \u0634\u064e\u064a\u0652\u0621\u064d \u0631\u0651\u0650\u0632\u0652\u0642\u064b\u0627 \u0645\u0651\u0650\u0646 \u0644\u0651\u064e\u062f\u064f\u0646\u0651\u064e\u0627 \u0648\u064e\u0644\u064e\u0670\u0643\u0650\u0646\u0651\u064e \u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa qaalooo in nattabi'il hudaa ma'aka nutakhattaf min ardinaa; awalam numakkkil lahum haraman aaminany yujbaaa ilaihi samaraatu kulli shai'ir rizqam mil ladunnaa wa laakinna aksarahum laa ya'lamoon",
        translation: "Dan mereka berkata, \u201cJika kami mengikuti petunjuk bersama engkau, niscaya kami akan diusir dari negeri kami.\u201d (Allah berfirman) Bukankah Kami telah meneguhkan kedudukan mereka dalam tanah haram (tanah suci) yang aman, yang didatangkan ke tempat itu buah-buahan dari segala macam (tumbuh-tumbuhan) sebagai rezeki (bagimu) dari sisi Kami? Tetapi kebanyakan mereka tidak mengetahui.",
        shortTafsir: "Dan untuk menjelaskan alasan mengapa mereka tetap memegang teguh kepercayaan yang mereka anut selama ini, mereka orang-orang musyrik Mekkah berkata kepada Rasul, \u201cJika kami mengikuti petunjuk itu dengan memeluk Islam dan bergabung bersama engkau, wahai Nabi Muhammad, yang ajaranmu sangat berbeda dengan kepercayaan masyarakat Arab, niscaya kami akan diusir dan diculik dari negeri kami\u00a0serta kekuasaan kami akan direbut.\u201d Mereka bohong dengan alasan mereka itu. Allah membantah alasan mereka itu dengan berfirman, \u201cBagaimana mereka berucap demikian, padahal bukankah Kami telah meneguhkan kedudukan mereka dalam tanah haram, yakni tanah suci Mekah, dengan menjadikan wilayah tempat tinggal mereka sebagai negeri yang aman dari serangan dan pembunuhan; yang terus-menerus dan senantiasa sepanjang waktu didatangkan ke tempat itu buah-buahan dari segala macam tumbuh-tumbuhan sebagai rezeki bagimu dari sisi Kami kendati mereka kafir? Sungguh, dalih mereka itu tidak logis dan apa yang mereka khawatirkan itu tidak terjadi, tetapi kebanyakan mereka tidak mengetahui keagungan karunia tersebut.\"",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3309",
      ),
      Ayah(
        numberInSurah: 58,
        numberInQuran: 3310,
        juz: 20,
        page: 392,
        arab: "\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0642\u064e\u0631\u0652\u064a\u064e\u0629\u064d \u0628\u064e\u0637\u0650\u0631\u064e\u062a\u0652 \u0645\u064e\u0639\u0650\u064a\u0634\u064e\u062a\u064e\u0647\u064e\u0627 \u06d6 \u0641\u064e\u062a\u0650\u0644\u0652\u0643\u064e \u0645\u064e\u0633\u064e\u0627\u0643\u0650\u0646\u064f\u0647\u064f\u0645\u0652 \u0644\u064e\u0645\u0652 \u062a\u064f\u0633\u0652\u0643\u064e\u0646 \u0645\u0651\u0650\u0646 \u0628\u064e\u0639\u0652\u062f\u0650\u0647\u0650\u0645\u0652 \u0625\u0650\u0644\u0651\u064e\u0627 \u0642\u064e\u0644\u0650\u064a\u0644\u064b\u0627 \u06d6 \u0648\u064e\u0643\u064f\u0646\u0651\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u0627\u0644\u0652\u0648\u064e\u0627\u0631\u0650\u062b\u0650\u064a\u0646\u064e",
        transliteration: "Wa kam ahlaknaa min qaryatim batirat ma'eeshatahaa fatilka masaainuhum lam tuskam mim ba'dihim illaa qaleelaa; wa kunnaa Nahnul waariseen",
        translation: "Dan betapa banyak (penduduk) negeri yang sudah bersenang-senang dalam kehidupannya yang telah Kami binasakan, maka itulah tempat kediaman mereka yang tidak didiami (lagi) setelah mereka, kecuali sebagian kecil. Dan Kamilah yang mewarisinya.\u201d",
        shortTafsir: "Mereka tidak mengambil pelajaran dari sejarah generasi masa lampau yang mendapatkan sanksi dan kebinasaan. Dan padahal betapa banyak negeri bersama penduduknya yang sudah bersenang-senang dalam kehidupannya yang telah Kami binasakan akibat keangkuhan dan kedurhakaan penduduknya dengan tidak mensyukuri kenyamanan hidup yang telah Kami anugerahkan kepada mereka. Maka lihatlah, itulah tempat kediaman mereka yang tidak didiami lagi oleh manusia setelah mereka, karena penduduknya telah dipunahkan dan kediaman mereka sudah tidak layak huni, kecuali sebagian kecil yang digunakan secara singkat oleh orang-orang yang kebetulan melewatinya. Setelah kebinasaan para pendurhaka itu, tidak ada lagi yang memiliki kota itu, dan Kamilah yang mewarisinya.\u201d Setelah mereka hancur, tempat itu sudah kosong dan tidak dimakmurkan lagi, hingga kembalilah ia kepada pemiliknya yang hakiki yaitu Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3310",
      ),
      Ayah(
        numberInSurah: 59,
        numberInQuran: 3311,
        juz: 20,
        page: 392,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0631\u064e\u0628\u0651\u064f\u0643\u064e \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u062d\u064e\u062a\u0651\u064e\u0649\u0670 \u064a\u064e\u0628\u0652\u0639\u064e\u062b\u064e \u0641\u0650\u064a \u0623\u064f\u0645\u0651\u0650\u0647\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064b\u0627 \u064a\u064e\u062a\u0652\u0644\u064f\u0648 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0622\u064a\u064e\u0627\u062a\u0650\u0646\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u0651\u064e\u0627 \u0645\u064f\u0647\u0652\u0644\u0650\u0643\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0631\u064e\u0649\u0670 \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0647\u0652\u0644\u064f\u0647\u064e\u0627 \u0638\u064e\u0627\u0644\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa maa kaana Rabbuka muhlikal quraa hattaa yab'asa feee ummihaa Rasoolany yatloo 'alaihim aayaatina; wa maa kunnaa muhlikil quraaa illaa wa ahluhaa zaalimoon",
        translation: "Dan Tuhanmu tidak akan membinasakan negeri-negeri, sebelum Dia mengutus seorang rasul di ibukotanya yang membacakan ayat-ayat Kami kepada mereka; dan tidak pernah (pula) Kami membinasakan (penduduk) negeri; kecuali penduduknya melakukan kezaliman.",
        shortTafsir: "Jangan menduga bahwa kehancuran negeri-negeri terjadi dengansewenang-wenang. Tidak, Allah Maha adil, dan karena itu Tuhanmu tidak mungkin akan membinasakan negeri-negeri di sekitar Mekah dan atau penduduknya pada masamu, wahai Nabi Muhammad, betapa pun besarnya kedurhakaan mereka, sebelum Dia mengutus seorang rasul di ibukotanya, yaitu Mekah, yang membacakan ayat-ayat Kami kepada mereka; dan tidak pernah pula Kami membinasakan penduduk negeri setelah Kami mengutus rasul atau pemberi peringatan; kecuali penduduknya melakukan kezaliman terhadap diri mereka sendiri dengan kufur dan maksiat kepada Allah, sehingga mereka pantas menerima hukuman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3311",
      ),
      Ayah(
        numberInSurah: 60,
        numberInQuran: 3312,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0634\u064e\u064a\u0652\u0621\u064d \u0641\u064e\u0645\u064e\u062a\u064e\u0627\u0639\u064f \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0632\u0650\u064a\u0646\u064e\u062a\u064f\u0647\u064e\u0627 \u06da \u0648\u064e\u0645\u064e\u0627 \u0639\u0650\u0646\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0648\u064e\u0623\u064e\u0628\u0652\u0642\u064e\u0649\u0670 \u06da \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u0642\u0650\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Wa maaa ooteetum min shai'in famataa'ul hayaatid dunyaa wa zeenatuhaa; wa maa 'indal laahi khairunw wa abqaa; afalaa ta'qiloon",
        translation: "Dan apa saja (kekayaan, jabatan, keturunan) yang diberikan kepada kamu, maka itu adalah kesenangan hidup duniawi dan perhiasannya; sedang apa yang di sisi Allah adalah lebih baik dan lebih kekal. Tidakkah kamu mengerti?",
        shortTafsir: "Kaum musyrik enggan beriman karena khawatir diculik, ditawan dan dirampas hartanya. Sebenarnya, bahaya yang harus ditakuti itu adalah yang bersumber dari Allah akibat kedurhakaan. Kerugian jiwa dan harta di dunia tidak seberapa kerugian di akhirat akibat durhaka kepada Allah. Dan ketahuilah bahwa apa saja kekayaan, jabatan, keturunan dan lainnya, yang diberikan oleh Allah melalui siapa pun kepada kamu, maka itu adalah kesenangan hidup duniawi dan perhiasannya yang bersifat terbatas dan sementara, sehingga akan segera lenyap dan binasa; sedang apa yang di sisi Allah di akhirat kelak, yang disediakan untuk untuk orang-orang yang taat kepada-Nya, adalah lebih baik karena tidak mengandung bahaya dan mudarat, dan di samping itu lebih kekal karena tidak akan punah sama sekali. Tidakkah kamu menggunakan akal pikiran sehingga kamu mengerti mana yang baik dan mana yang buruk?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3312",
      ),
      Ayah(
        numberInSurah: 61,
        numberInQuran: 3313,
        juz: 20,
        page: 393,
        arab: "\u0623\u064e\u0641\u064e\u0645\u064e\u0646 \u0648\u064e\u0639\u064e\u062f\u0652\u0646\u064e\u0627\u0647\u064f \u0648\u064e\u0639\u0652\u062f\u064b\u0627 \u062d\u064e\u0633\u064e\u0646\u064b\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0644\u064e\u0627\u0642\u0650\u064a\u0647\u0650 \u0643\u064e\u0645\u064e\u0646 \u0645\u0651\u064e\u062a\u0651\u064e\u0639\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u064e\u062a\u064e\u0627\u0639\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u062b\u064f\u0645\u0651\u064e \u0647\u064f\u0648\u064e \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u062d\u0652\u0636\u064e\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Afamanw wa'adnaahu wa'dan hasanan fahuwa laaqeehi kamam matta'naahu mataa'al hayaatid dunyaa summa huwa Yawmal Qiyaamati minal muhdareen",
        translation: "Maka apakah sama orang yang Kami janjikan kepadanya suatu janji yang baik (surga) lalu dia memperolehnya, dengan orang yang Kami berikan kepadanya kesenangan hidup duniawi; kemudian pada hari Kiamat dia termasuk orang-orang yang diseret (ke dalam neraka)?",
        shortTafsir: "Maka, jika demikian itu halnya, apakah sama orang yang Kami janjikan kepadanya suatu janji yang baik, yaitu surga dengan segala kenikmatannya yang abadi, lalu berkat anugerah Kami dia memperolehnya, apakah dia itu sama dengan orang yang Kami berikan kepadanya kesenangan hidup duniawi, tetapi tidak dipergunakannya untuk mencari kebahagiaan hidup di akhirat, sehingga kemudian pada hari Kiamat dia termasuk orang-orang yang diseret ke dalam neraka untuk dimintai pertanggunggjawabannya? Tentu tidaklah sama. Kelompok yang pertama adalah orang yang beriman dan beramal saleh yang berhak mendapatkan janji baik Allah berupa pahala dan surga, sedangkan kelompok yang kedua adalah orang kafir yang mengerjakan keburukan serta tertipu oleh kesenangan dunia dan perhiasannya, yang akan binasa dalam siksaan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3313",
      ),
      Ayah(
        numberInSurah: 62,
        numberInQuran: 3314,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u0652\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0632\u0652\u0639\u064f\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa Yawma yunaadeehim fa-yaqoolu aina shurakaaa 'iyal lazeena kuntum taz'umoon",
        translation: "Dan (ingatlah) pada hari ketika Dia (Allah) menyeru mereka dan berfirman, \u201cDi manakah sekutu-sekutu-Ku yang dahulu kamu sangka?\u201d",
        shortTafsir: "Dan ingatlah dan ingatkan pula umatmu, wahai Nabi Muhammad, tentang siksa yang akan dialami oleh orang-orang musyrik di akhirat kelak, yaitu pada hari ketika mereka berdiri di hadapan Allah untuk dimintakan pertanggungjawaban, Dia menyeru mereka dengan panggilan yang menghinakan dan berfirman, \u201cDi manakah sembahan-sembahan yang kamu anggap sebagai sekutu-sekutu-Ku yang dahulu kamu sangka sebagai tuhan-tuhan yang akan membela dan menolong kamu?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3314",
      ),
      Ayah(
        numberInSurah: 63,
        numberInQuran: 3315,
        juz: 20,
        page: 393,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062d\u064e\u0642\u0651\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0642\u064e\u0648\u0652\u0644\u064f \u0631\u064e\u0628\u0651\u064e\u0646\u064e\u0627 \u0647\u064e\u0670\u0624\u064f\u0644\u064e\u0627\u0621\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u0646\u064e\u0627 \u0623\u064e\u063a\u0652\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f\u0645\u0652 \u0643\u064e\u0645\u064e\u0627 \u063a\u064e\u0648\u064e\u064a\u0652\u0646\u064e\u0627 \u06d6 \u062a\u064e\u0628\u064e\u0631\u0651\u064e\u0623\u0652\u0646\u064e\u0627 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0625\u0650\u064a\u0651\u064e\u0627\u0646\u064e\u0627 \u064a\u064e\u0639\u0652\u0628\u064f\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Qaalal lazeena haqqa 'alaihimul qawlu Rabbanaa haaa'ulaaa'il lazeena aghwainaa aghwainaahu kamaa ghawainaa tabarraanaaa ilaika maa kaanoo iyyaanaa ya'budoon",
        translation: "Orang-orang yang sudah pasti akan mendapatkan hukuman berkata, \u201cYa Tuhan kami, mereka inilah orang-orang yang kami sesatkan itu; kami telah menyesatkan mereka sebagaimana kami (sendiri) sesat, kami menyatakan kepada Engkau berlepas diri (dari mereka), mereka sekali-kali tidak menyembah kami.\u201d",
        shortTafsir: "Mendengar pertanyaan itu, orang-orang yang sudah pasti akan mendapatkan hukuman Allah, yaitu para pemimpin kaum kafir, berkata, \u201cYa Tuhan Pemelihara dan Pelimpah aneka nikmat kepada kami, kami mengaku bahwa mereka inilah orang-orang yang dahulu kami sesatkan itu, melalui ucapan, tindakan dan keteladanan kami. Dengan mengharap akan dibebaskan atau diringankan dari siksa mereka melontarkan pengakuan dengan berkata, \u201cKami mengaku telah menyesatkan mereka sebagaimana kami sendiri sesat. Tetapi hal itu karena mereka sendiri telah memilih dan menerima kekufuran sebagaimana halnya kami. Pada hari ini, kami menyatakan kepada Engkau berlepas diri dari segala sesuatu tentang mereka, dan juga dari kekufuran yang mereka pilih di dunia. Mereka sekali-kali tidak menyembah atau menaati kami, tetapi mereka menyembah dan menuruti hawa nafsu mereka sendiri.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3315",
      ),
      Ayah(
        numberInSurah: 64,
        numberInQuran: 3316,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u0642\u0650\u064a\u0644\u064e \u0627\u062f\u0652\u0639\u064f\u0648\u0627 \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u062f\u064e\u0639\u064e\u0648\u0652\u0647\u064f\u0645\u0652 \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u062c\u0650\u064a\u0628\u064f\u0648\u0627 \u0644\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0631\u064e\u0623\u064e\u0648\u064f\u0627 \u0627\u0644\u0652\u0639\u064e\u0630\u064e\u0627\u0628\u064e \u06da \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u0651\u064e\u0647\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0647\u0652\u062a\u064e\u062f\u064f\u0648\u0646\u064e",
        transliteration: "Wa qeelad 'oo shurakaaa'akum fada'awhum falam yastajeeboo lahum wa ra awul 'azaab; law annahum kaanoo yahtadoon",
        translation: "Dan dikatakan (kepada mereka), \u201cSerulah sekutu-sekutumu,\u201d lalu mereka menyerunya, tetapi yang diseru tidak menyambutnya, dan mereka melihat azab. (Mereka itu berkeinginan) sekiranya mereka dahulu menerima petunjuk.",
        shortTafsir: "Tidak hanya sampai di situ kecaman dan siksaan batin yang mere-ka peroleh. Dan pada hari kiamat dikatakan kepada mereka yang menyekutukan Allah, \u201cSerulah sekutu-sekutumu yang dahulu kamu sembah selain Allah, agar dapat membantu kamu dalam situasi sulit ini seba-gaimana dugaan kamu ketika masih hidup.\u201d Lalu, karena bingung tidak mengetahui apalagi yang harus mereka kerjakan, mereka menyerunya, tetapi yang diseru tidak menyambutnya, dan saat itu mereka semua melihat azab yang tersedia dan yakin bahwa mereka akan disiksa dengannya. Ketika itu mereka menyesal dan berkeinginan sekiranya mereka dahulu menerima petunjuk kebenaran, sehingga mereka tidak mendapat siksa. Akan tetapi, apalah artinya penyesalan di kemudian hari.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3316",
      ),
      Ayah(
        numberInSurah: 65,
        numberInQuran: 3317,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0645\u064e\u0627\u0630\u064e\u0627 \u0623\u064e\u062c\u064e\u0628\u0652\u062a\u064f\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e",
        transliteration: "Wa Yawma yunaadeehim fa yaqoolu maazaaa ajabtumul mursaleen",
        translation: "Dan (ingatlah) pada hari ketika Dia (Allah) menyeru mereka, dan berfirman, \u201cApakah jawabanmu terhadap para rasul?\u201d",
        shortTafsir: "Setelah dikecam karena perbuatan syirik, mereka ditanyai tentang sikap mereka terhadap para rasul Allah. Dan ingatlah, dan ingatkan pula umatmu wahai Nabi Muhammad pada hari ketika Dia menyeru mereka, dan berfirman, \u201cApakah jawabanmu terhadap para rasul ketika mereka mengajak kamu beriman dan beramal saleh?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3317",
      ),
      Ayah(
        numberInSurah: 66,
        numberInQuran: 3318,
        juz: 20,
        page: 393,
        arab: "\u0641\u064e\u0639\u064e\u0645\u0650\u064a\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0623\u064e\u0646\u0628\u064e\u0627\u0621\u064f \u064a\u064e\u0648\u0652\u0645\u064e\u0626\u0650\u0630\u064d \u0641\u064e\u0647\u064f\u0645\u0652 \u0644\u064e\u0627 \u064a\u064e\u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Fa'amiyat 'alaihimul ambaaa'u Yawma'izin fahum laa yatasaaa'aloon",
        translation: "Maka gelaplah bagi mereka segala macam alasan pada hari itu, karena itu mereka tidak saling bertanya.",
        shortTafsir: "Maka, gelap dan tidak tampak lah bagi mereka berita-berita penting dan segala macam alasan untuk menjawab pertanyaan pada hari itu, sehingga mereka bungkam tidak dapat menjawab. Karena itu pula, mereka tidak saling bertanya sebab semua telah yakin bahwa tidak ada jawaban yang dapat menyelamatkan mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3318",
      ),
      Ayah(
        numberInSurah: 67,
        numberInQuran: 3319,
        juz: 20,
        page: 393,
        arab: "\u0641\u064e\u0623\u064e\u0645\u0651\u064e\u0627 \u0645\u064e\u0646 \u062a\u064e\u0627\u0628\u064e \u0648\u064e\u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0641\u064e\u0639\u064e\u0633\u064e\u0649\u0670 \u0623\u064e\u0646 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0644\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Fa ammaa man taaba wa aamana wa 'amila saalihan fa'asaaa ai yakoona minal mufliheen",
        translation: "Maka adapun orang yang bertobat dan beriman, serta mengerjakan kebajikan, maka mudah-mudahan dia termasuk orang yang beruntung.",
        shortTafsir: "Demikian itulah keadaan orang yang mati dalam keadaan musyrik. Maka adapun orang yang berbuat syirik dan kufur, lalu bertobat dan beriman secara baik dan benar, serta membuktikan keimanannya itu dengan mengerjakan kebajikan dengan penuh keikhlasan, maka mudah-mudahan dia termasuk orang yang beruntung memperoleh kebahagiaan di dunia dan akhirat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3319",
      ),
      Ayah(
        numberInSurah: 68,
        numberInQuran: 3320,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u062e\u0652\u0644\u064f\u0642\u064f \u0645\u064e\u0627 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0648\u064e\u064a\u064e\u062e\u0652\u062a\u064e\u0627\u0631\u064f \u06d7 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0652\u062e\u0650\u064a\u064e\u0631\u064e\u0629\u064f \u06da \u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u0670 \u0639\u064e\u0645\u0651\u064e\u0627 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u064f\u0648\u0646\u064e",
        transliteration: "Wa Rabbuka yakhuluqu maa yashaaa'u wa yakhtaar; maa kaana lahumul khiyarah; Subhannal laahi wa Ta'aalaa 'ammmaa yushrikoon",
        translation: "Dan Tuhanmu menciptakan dan memilih apa yang Dia kehendaki. Bagi mereka (manusia) tidak ada pilihan. Mahasuci Allah dan Mahatinggi Dia dari apa yang mereka persekutukan.",
        shortTafsir: "Begitulah yang akan dialami orang-orang musyrik di akhirat kelak. Semuanya kembali kepada hikmah dan kebijaksanaan Allah dalam segala hal, termasuk menjadikan hati yang terbuka untuk menerima hidayah dan hati yang tertutup. Dan Tuhan Pemelihara-mu menciptakan apa dan siapa yang Dia kehendaki untuk diciptakan, dan memilih apa dan siapa yang Dia kehendaki untuk menerima anugerah dan mengemban amanat dari-Nya. Sekali-kali bagi mereka yang diciptakan, baik manusia maupun selainnya, tidak ada pilihan lain kecuali menerima ketetapan-Nya, suka atau tidak suka. Mahasuci Allah dari segala sifat dan tindakan yang buruk atau salah dan Mahatinggi Dia dari apa yang mereka persekutukan dengan mengangkat berhala-berhala sebagai sembahan selain Allah. Apa pun yang dialami oleh manusia, senang atau sedih, bukan mereka yang memilihnya, tetapi Allah yang memilihnya, sehingga harus diterima dengan lapang dada. Manusia hanya diminta untuk berusaha semaksimal mungkin dan menyerahkan hasilnya kepada Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3320",
      ),
      Ayah(
        numberInSurah: 69,
        numberInQuran: 3321,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u0631\u064e\u0628\u0651\u064f\u0643\u064e \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0627 \u062a\u064f\u0643\u0650\u0646\u0651\u064f \u0635\u064f\u062f\u064f\u0648\u0631\u064f\u0647\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u064a\u064f\u0639\u0652\u0644\u0650\u0646\u064f\u0648\u0646\u064e",
        transliteration: "Wa Rabbuka ya'lamu maa tukinnu sudooruhum wa maa yu'linoon",
        translation: "Dan Tuhanmu mengetahui apa yang disembunyikan dalam dada mereka dan apa yang mereka nyatakan.",
        shortTafsir: "Dan, di samping itu, Tuhan Pemelihara-mu wahai Rasul, mengetahui apa yang disembunyikan dalam dada mereka berupa permusuhan terhadapmu, dan apa yang mereka nyatakan secara lisan, berupa celaan-celaan kepadamu dan protes terhadap pemilihan dirimu sebagai penyampai pesan-pesan suci.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3321",
      ),
      Ayah(
        numberInSurah: 70,
        numberInQuran: 3322,
        juz: 20,
        page: 393,
        arab: "\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06d6 \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649\u0670 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u06d6 \u0648\u064e\u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa Huwal laahu laaa ilaaha illaa Huwa lahul hamdu fil oolaa wal Aakhirati wa lahul hukmu wa ilaihi turja'oon",
        translation: "Dan Dialah Allah, tidak ada tuhan (yang berhak disembah) selain Dia, segala puji bagi-Nya di dunia dan di akhirat, dan bagi-Nya segala penentuan dan kepada-Nya kamu dikembalikan.",
        shortTafsir: "Dan Tuhanmu Yang mengetahui apa yang disembunyikan dalam dada mereka dan apa yang mereka nyatakan itu Dialah Allah Yang Mahabenar. Tidak ada tuhan Yang Mahakuasa dan berhak disembah selain Dia. Segala puji hanya bagi-Nya di dunia atas segala nikmat dan petunjuk-Nya, dan pujian di akhirat hanya bagi-Nya atas keadilan dan pahala dari-Nya, dan hanya bagi-Nya pula segala penentuan keputusan menyangkut segala sesuatu, dan hanya kepada-Nya kamu dikembalikan untuk dimintakan pertanggung-jawaban dan mendapat balasan setelah kamu mati.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3322",
      ),
      Ayah(
        numberInSurah: 71,
        numberInQuran: 3323,
        juz: 20,
        page: 394,
        arab: "\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0633\u064e\u0631\u0652\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0636\u0650\u064a\u064e\u0627\u0621\u064d \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Qul ara'aitum in ja'alal laahu 'alaikumul laila sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaa teekum bidiyaaa'in afalaa tasma'oon",
        translation: "Katakanlah (Muhammad), \u201cBagaimana pendapatmu, jika Allah menjadikan untukmu malam itu terus-menerus sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan sinar terang kepadamu? Apakah kamu tidak mendengar?\u201d",
        shortTafsir: "Sebagai bukti atas kuasa Allah dan ilmunya yang menyeluruh serta kewajaran-Nya untuk dipuja dan dipuji, katakanlah wahai Nabi Muhammad, kepada siapa saja yang meragukan itu semua, \u201cBagaimana pendapatmu, jika Allah menjadikan untukmu malam dengan kegelapan dan keheningannya itu terus-menerus demikian tanpa adanya siang sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan sinar terang kepadamu yang kamu pakai untuk melihat dengan baik, bekerja dan melakukan aktivitas lainnya? Kamu pasti tidak punya Tuhan yang dapat melakukan hal itu selain Allah. Lalu, jika demikian apakah kamu tidak mau mendengar untuk menjadikannya sebagai bahan renungan dan pelajaran?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3323",
      ),
      Ayah(
        numberInSurah: 72,
        numberInQuran: 3324,
        juz: 20,
        page: 394,
        arab: "\u0642\u064f\u0644\u0652 \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0625\u0650\u0646 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u064f \u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0633\u064e\u0631\u0652\u0645\u064e\u062f\u064b\u0627 \u0625\u0650\u0644\u064e\u0649\u0670 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0645\u064e\u0646\u0652 \u0625\u0650\u0644\u064e\u0670\u0647\u064c \u063a\u064e\u064a\u0652\u0631\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u064a\u064e\u0623\u0652\u062a\u0650\u064a\u0643\u064f\u0645 \u0628\u0650\u0644\u064e\u064a\u0652\u0644\u064d \u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0646\u064e \u0641\u0650\u064a\u0647\u0650 \u06d6 \u0623\u064e\u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0628\u0652\u0635\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Qul ara'aitum in ja'alal laahu 'alaikumun nahaara sarmadan ilaa Yawmil Qiyaamati man ilaahun ghairul laahi yaateekum bilailin taskunoona feehi afalaa tubsiroon",
        translation: "Katakanlah (Muhammad), \u201cBagaimana pendapatmu, jika Allah menjadikan untukmu siang itu terus-menerus sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan malam kepadamu sebagai waktu istirahatmu? Apakah kamu tidak memperhatikan?\u201d",
        shortTafsir: "Katakanlah juga kepada mereka wahai Nabi Muhammad, \u201cBagaimana pendapatmu, jika Allah menjadikan untukmu semua siang yang demikian terang itu terus-menerus demikian tanpa adanya malam yang gelap dan hening sampai hari Kiamat. Siapakah tuhan selain Allah yang akan mendatangkan malam kepadamu sebagai waktu istirahatmu dari kelelahan akibat aktivitas di siang hari? Kamu pasti tidak punya Tuhan selain Allah yang dapat melakukan hal itu. Jika demikian, apakah kamu tidak memperhatikan tanda-tanda kebesaran Allah berupa perputaran siang dan malam sehingga kalian beriman dan mendapatkan petunjuk?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3324",
      ),
      Ayah(
        numberInSurah: 73,
        numberInQuran: 3325,
        juz: 20,
        page: 394,
        arab: "\u0648\u064e\u0645\u0650\u0646 \u0631\u0651\u064e\u062d\u0652\u0645\u064e\u062a\u0650\u0647\u0650 \u062c\u064e\u0639\u064e\u0644\u064e \u0644\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0644\u0651\u064e\u064a\u0652\u0644\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064e\u0647\u064e\u0627\u0631\u064e \u0644\u0650\u062a\u064e\u0633\u0652\u0643\u064f\u0646\u064f\u0648\u0627 \u0641\u0650\u064a\u0647\u0650 \u0648\u064e\u0644\u0650\u062a\u064e\u0628\u0652\u062a\u064e\u063a\u064f\u0648\u0627 \u0645\u0650\u0646 \u0641\u064e\u0636\u0652\u0644\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0639\u064e\u0644\u0651\u064e\u0643\u064f\u0645\u0652 \u062a\u064e\u0634\u0652\u0643\u064f\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa mir rahmatihee ja'ala lakumul laila wannahaara litaskunoo feehi wa litabtaghoo min fadlihee wa la'allakum tashkuroon",
        translation: "Dan adalah karena rahmat-Nya, Dia jadikan untukmu malam dan siang, agar kamu beristirahat pada malam hari dan agar kamu mencari sebagian karunia-Nya (pada siang hari) dan agar kamu bersyukur kepada-Nya.",
        shortTafsir: "Dan adalah karena rahmat-Nya yang mencakup segala sesuatu, Dia jadikan untukmu malam dan siang secara bergantian. Dengan keduanya Allah menganugerahkan kepada kamu banyak manfaat. Dia menjadikan malam gelap gulita agar kamu beristirahat pada malam hari setelah sepanjang hari kamu bekerja sehingga memerlukan istirahat. Dan Dia jadikan siang terang benderang agar kamu bersungguh-sungguh mencari sebagian karunia-Nya pada siang hari yang terang itu, dan juga agar kamu bersyukur kepada-Nya atas segala nikmat yang dianugerahkan-Nya kepadamu.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3325",
      ),
      Ayah(
        numberInSurah: 74,
        numberInQuran: 3326,
        juz: 20,
        page: 394,
        arab: "\u0648\u064e\u064a\u064e\u0648\u0652\u0645\u064e \u064a\u064f\u0646\u064e\u0627\u062f\u0650\u064a\u0647\u0650\u0645\u0652 \u0641\u064e\u064a\u064e\u0642\u064f\u0648\u0644\u064f \u0623\u064e\u064a\u0652\u0646\u064e \u0634\u064f\u0631\u064e\u0643\u064e\u0627\u0626\u0650\u064a\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0643\u064f\u0646\u062a\u064f\u0645\u0652 \u062a\u064e\u0632\u0652\u0639\u064f\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Wa Yawma yunaadeehim fa yaqoolu aina shurakaaa'iyal lazeena kuntum tazz'umoon",
        translation: "Dan (ingatlah) pada hari ketika Dia (Allah) menyeru mereka, dan berfirman, \u201cDi manakah sekutu-sekutu-Ku yang dahulu kamu sangka?\u201d",
        shortTafsir: "Dan sebagai bentuk kecaman dan ancaman terhadap orang-orang musyrik, ingatlah, dan ingatkan pula umatmu, wahai Nabi Muhammad, pada hari ketika mereka berdiri di hadapan Allah untuk dimintakan pertanggungjawaban, Dia menyeru mereka yang musyrik itu dengan panggilan yang menghinakan, dan berfirman, \u201cDi manakah sekutu-sekutu-Ku yang dahulu kamu sangka sebagai tuhan-tuhan yang akan membela dan menolong kamu?\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3326",
      ),
      Ayah(
        numberInSurah: 75,
        numberInQuran: 3327,
        juz: 20,
        page: 394,
        arab: "\u0648\u064e\u0646\u064e\u0632\u064e\u0639\u0652\u0646\u064e\u0627 \u0645\u0650\u0646 \u0643\u064f\u0644\u0651\u0650 \u0623\u064f\u0645\u0651\u064e\u0629\u064d \u0634\u064e\u0647\u0650\u064a\u062f\u064b\u0627 \u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627 \u0647\u064e\u0627\u062a\u064f\u0648\u0627 \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064e\u0643\u064f\u0645\u0652 \u0641\u064e\u0639\u064e\u0644\u0650\u0645\u064f\u0648\u0627 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u064e \u0644\u0650\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0636\u064e\u0644\u0651\u064e \u0639\u064e\u0646\u0652\u0647\u064f\u0645 \u0645\u0651\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa naza'naa min kulli ummatin shaheedan faqulnaa haatoo burhaanakum fa'alimooo annal haqqa lillaahi wa dalla 'anhum maa kaanoo yaftaroon",
        translation: "Dan Kami datangkan dari setiap umat seorang saksi, lalu Kami katakan, \u201cKemukakanlah bukti kebenaranmu,\u201d maka tahulah mereka bahwa yang hak (kebenaran) itu milik Allah dan lenyaplah dari mereka apa yang dahulu mereka ada-adakan.",
        shortTafsir: "Kaum musyrik tidak dapat menjawab. Oleh karenanya Allah menghadirkan saksi, dan untuk maksud itu, Allah berfirman, \"Kami datangkan dari setiap umat seorang saksi, yaitu nabi dan rasul yang dahulu diutus kepada mereka, yang bersaksi atas kedurhakaan yang mereka lakukan di dunia. Lalu pada saat itu, Kami katakan kepada orang-orang yang melanggar di antara mereka, \u201cKemukakanlah bukti kebenaranmu yang kamu gunakan untuk membenarkan kemusyrikan\u201d. Mereka tidak mampu mendatangkannya, maka dengan segera tahulah dan sadarlah mereka bahwa yang hak, yaitu kebenaran dalam hal ketuhanan dan lain-lain, itu hanya milik Allah dan lenyaplah dari mereka lagi binasa apa, yakni kebohongan-kebohongan, yang dahulu ketika di dunia mereka selalu ada-adakan. Semua itu tidak berguna bagi mereka, dan hanya mendatangkan bahaya dan menjerumuskan mereka ke dalam neraka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3327",
      ),
      Ayah(
        numberInSurah: 76,
        numberInQuran: 3328,
        juz: 20,
        page: 394,
        arab: "\u06de \u0625\u0650\u0646\u0651\u064e \u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064e \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0648\u0652\u0645\u0650 \u0645\u064f\u0648\u0633\u064e\u0649\u0670 \u0641\u064e\u0628\u064e\u063a\u064e\u0649\u0670 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0648\u064e\u0622\u062a\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0643\u064f\u0646\u064f\u0648\u0632\u0650 \u0645\u064e\u0627 \u0625\u0650\u0646\u0651\u064e \u0645\u064e\u0641\u064e\u0627\u062a\u0650\u062d\u064e\u0647\u064f \u0644\u064e\u062a\u064e\u0646\u064f\u0648\u0621\u064f \u0628\u0650\u0627\u0644\u0652\u0639\u064f\u0635\u0652\u0628\u064e\u0629\u0650 \u0623\u064f\u0648\u0644\u0650\u064a \u0627\u0644\u0652\u0642\u064f\u0648\u0651\u064e\u0629\u0650 \u0625\u0650\u0630\u0652 \u0642\u064e\u0627\u0644\u064e \u0644\u064e\u0647\u064f \u0642\u064e\u0648\u0652\u0645\u064f\u0647\u064f \u0644\u064e\u0627 \u062a\u064e\u0641\u0652\u0631\u064e\u062d\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0641\u064e\u0631\u0650\u062d\u0650\u064a\u0646\u064e",
        transliteration: "Inna Qaaroona kaana min qawmi Moosaa fabaghaaa 'alaihim wa aatainaahu minal kunoozi maaa inna mafaati hahoo latanooo'u bil'usbati ulil quwwati iz qaala lahoo qawmuhoo laa tafrah innal laahaa laa yuhibbul fariheen",
        translation: "Sesungguhnya Karun termasuk kaum Musa, tetapi dia berlaku zalim terhadap mereka, dan Kami telah menganugerahkan kepadanya perbendaharaan harta yang kunci-kuncinya sungguh berat dipikul oleh sejumlah orang yang kuat-kuat. (Ingatlah) ketika kaumnya berkata kepadanya, \u201cJanganlah engkau terlalu bangga. Sungguh, Allah tidak menyukai orang yang membanggakan diri.\u201d",
        shortTafsir: "Kekuatan dan kekuasaan akan berakhir dengan kebinasaan karena kedurhakaan dan kezaliman, seperti yang terjadi pada Fir'aun. Begitu juga dengan kekuatan harta dan pengetahuan yang juga berakhir dengan kebinasaan saat disertai dengan kedurhakaan dan keangkuhan, seperti yang menerima Karun. Sesungguhnya Karun termasuk kaum Musa yang hidup semasa dengannya dan konon adalah anak Nabi Musa. Akan tetapi meski berasal dari keluarga terhormat, dia melampaui batas dengan berlaku zalim terhadap mereka dan sombong. Ia adalah seorang yang Kami beri nikmat dengan memasukkannya ke dalam kelompok kaum Nabi Musa, dan Kami telah menganugerahkan pula kepadanya perbendaharaan harta yang kunci-kunci gudang tempat penyimpanan hartanya itu sungguh sangat banyak sehingga terasa berat dipikul oleh sejumlah orang yang kuat-kuat. Itu baru kuncinya, ada pun harta kekayaannya, tidak mungkin dapat dipikul oleh orang yang sangat banyak sekali pun. Ingatlah ketika ia terpedaya oleh nikmat Allah yang dikaruniakan kepadanya dengan mengingkari dan tidak mensyukurinya, kaumnya menasihatinya dengan berkata kepadanya, \u201cJanganlah engkau terlalu bangga dengan harta kekayaan yang engkau miliki, kebanggaan yang menjadikanmu melupakan Allah yang menganugerahkan nikmat itu sehingga tidak bersyukur kepada-Nya. Sungguh, Allah tidak menyukai orang yang membanggakan diri.\u201d Orang-orang kafir Mekkah yang menentang Nabi Muhammad telah tertipu oleh harta mereka, sebab kekayaan mereka digunakan untuk menindas kaum Muslim. Padahal, harta benda mereka sangat sedikit jika dibandingkan dengan harta Karun. Orang kaya yang angkuh dan zalim akan berakhir dengan kebinasaan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3328",
      ),
      Ayah(
        numberInSurah: 77,
        numberInQuran: 3329,
        juz: 20,
        page: 394,
        arab: "\u0648\u064e\u0627\u0628\u0652\u062a\u064e\u063a\u0650 \u0641\u0650\u064a\u0645\u064e\u0627 \u0622\u062a\u064e\u0627\u0643\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064e \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0633\u064e \u0646\u064e\u0635\u0650\u064a\u0628\u064e\u0643\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u06d6 \u0648\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646 \u0643\u064e\u0645\u064e\u0627 \u0623\u064e\u062d\u0652\u0633\u064e\u0646\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u063a\u0650 \u0627\u0644\u0652\u0641\u064e\u0633\u064e\u0627\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u06d6 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064f \u0627\u0644\u0652\u0645\u064f\u0641\u0652\u0633\u0650\u062f\u0650\u064a\u0646\u064e",
        transliteration: "Wabtaghi feemaaa aataakal laahud Daaral Aakhirata wa laa tansa naseebaka minad dunyaa wa ahsin kamaaa ahsanal laahu ilaika wa laa tabghil fasaada fil ardi innal laaha laa yuhibbul mufsideen",
        translation: "Dan carilah (pahala) negeri akhirat dengan apa yang telah dianugerahkan Allah kepadamu, tetapi janganlah kamu lupakan bagianmu di dunia dan berbuatbaiklah (kepada orang lain) sebagaimana Allah telah berbuat baik kepadamu, dan janganlah kamu berbuat kerusakan di bumi. Sungguh, Allah tidak menyukai orang yang berbuat kerusakan.",
        shortTafsir: "Nasihat di atas tidak berarti seseorang hanya boleh beribadah murni (mahdah) dan melarang memperhatikan dunia. Berusahalah sekuat tenaga dan pikiran untuk memperoleh harta, dan carilah pahala negeri akhirat dengan apa yang telah dianugerahkan Allah kepadamu di dunia, berupa kekayaan dan karunia lainnya, dengan menginfakkan dan menggunakannya di jalan Allah. Akan tetapi pada saat yang sama janganlah kamu lupakan bagianmu dari kenikmatan di dunia dengan tanpa berlebihan. Dan berbuatbaiklah kepada semua orang dengan bersedekah sebagaimana atau disebabkan karena Allah telah berbuat baik kepadamu dengan mengaruniakan nikmat-Nya, dan janganlah kamu berbuat kerusakan dalam bentuk apa pun di bagian mana pun di bumi ini, dengan melampaui batas-batas yang telah ditetapkan oleh Allah. Sungguh, Allah tidak menyukai orang yang berbuat kerusakan dan akan memberikan balasan atas kejahatan tersebut.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3329",
      ),
      Ayah(
        numberInSurah: 78,
        numberInQuran: 3330,
        juz: 20,
        page: 395,
        arab: "\u0642\u064e\u0627\u0644\u064e \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u0649\u0670 \u0639\u0650\u0644\u0652\u0645\u064d \u0639\u0650\u0646\u062f\u0650\u064a \u06da \u0623\u064e\u0648\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0642\u064e\u062f\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u064f\u0648\u0646\u0650 \u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0623\u064e\u0634\u064e\u062f\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f \u0642\u064f\u0648\u0651\u064e\u0629\u064b \u0648\u064e\u0623\u064e\u0643\u0652\u062b\u064e\u0631\u064f \u062c\u064e\u0645\u0652\u0639\u064b\u0627 \u06da \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646 \u0630\u064f\u0646\u064f\u0648\u0628\u0650\u0647\u0650\u0645\u064f \u0627\u0644\u0652\u0645\u064f\u062c\u0652\u0631\u0650\u0645\u064f\u0648\u0646\u064e",
        transliteration: "Qaala innamaaa ootee tuhoo 'alaa 'ilmin 'indeee; awalam ya'lam annal laaha qad ahlaka min qablihee minal qurooni man huwa ashaddu minhu quwwatanw wa aksaru jam'aa; wa laa yus'alu 'an zunoobihimul mujrimoon",
        translation: "Dia (Karun) berkata, \u201cSesungguhnya aku diberi (harta itu), semata-mata karena ilmu yang ada padaku.\u201d Tidakkah dia tahu, bahwa Allah telah membinasakan umat-umat sebelumnya yang lebih kuat daripadanya, dan lebih banyak mengumpulkan harta? Dan orang-orang yang berdosa itu tidak perlu ditanya tentang dosa-dosa mereka.",
        shortTafsir: "Karun tidak menanggapi nasihat kaumnya, lupa diri dan tetap melupakan karunia Allah kepadanya. Dengan penuh kesombongan dia berkata, \u201cSesungguhnya aku diberi harta yang banyak ini, semata-mata karena ilmu dan kemampuan yang ada padaku. Tidak ada jasa siapa pun atas perolehanku itu. Semua karena kepandaianku dalam mengumpulkan harta.\u201d Demikian jawab Karun. Tidakkah dia tahu dan sadar, bahwa Allah telah membinasakan umat-umat yang tidak jauh dari masa sebelumnya, yakni sebelum Karun, yang lebih kuat fisik dan kemampuan serta pembantu-pembantu mereka daripadanya, dan lebih banyak mengumpulkan harta daripada Karun? Sungguh kedurhakaan Karun telah demikian jelas, dan oleh karenanya, orang-orang yang berdosa seperti Karun itu tidak perlu ditanya tentang dosa-dosa mereka, karena Allah telah mengetahui hal itu. Mereka akan masuk neraka, dan hanya akan ditanya dengan pertanyaan yang menghinakan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3330",
      ),
      Ayah(
        numberInSurah: 79,
        numberInQuran: 3331,
        juz: 20,
        page: 395,
        arab: "\u0641\u064e\u062e\u064e\u0631\u064e\u062c\u064e \u0639\u064e\u0644\u064e\u0649\u0670 \u0642\u064e\u0648\u0652\u0645\u0650\u0647\u0650 \u0641\u0650\u064a \u0632\u0650\u064a\u0646\u064e\u062a\u0650\u0647\u0650 \u06d6 \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u064a\u064e\u0627\u0629\u064e \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u064a\u064e\u0627 \u0644\u064e\u064a\u0652\u062a\u064e \u0644\u064e\u0646\u064e\u0627 \u0645\u0650\u062b\u0652\u0644\u064e \u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u064e \u0642\u064e\u0627\u0631\u064f\u0648\u0646\u064f \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0630\u064f\u0648 \u062d\u064e\u0638\u0651\u064d \u0639\u064e\u0638\u0650\u064a\u0645\u064d",
        transliteration: "Fakharaja 'alaa qawmihee fee zeenatih; qaalal lazeena yureedoonal hayaatad dunyaa yaalaita lanaa misla maaa ootiya Qaaroonu innahoo lazoo hazzin 'azeem",
        translation: "Maka keluarlah dia (Karun) kepada kaumnya dengan kemegahannya. Orang-orang yang menginginkan kehidupan dunia berkata, \u201cMudah-mudahan kita mempunyai harta kekayaan seperti apa yang telah diberikan kepada Karun, sesungguhnya dia benar-benar mempunyai keberuntungan yang besar.\u201d",
        shortTafsir: "Nasihat yang disampaikan kepada Karun tidak digubris olehnya. Bahkan, keangkuhannya semakin menjadi-jadi. Maka keluarlah dia kepada kaumnya, di depan khalayak ramai, dengan membangga-banggakan kemegahannya dan mempertontonkan kekayaan dan kekuatan yang dimilikinya, sehingga membuat silau orang yang lemah imannya. Melihat itu, orang-orang yang selalu menginginkan kehidupan dunia sebagai tumpuan dan tujuan hidupnya berkata, \u201cMudah-mudahan kita mempunyai harta kekayaan dan kedudukan seperti apa yang telah diberikan kepada Karun, sesungguhnya dia benar-benar mempunyai keberuntungan yang besar di dunia.\u201d Mereka tertipu olehnya dan ber-angan-angan untuk memiliki seperti yang dikaruniakan kepada Karun, yaitu harta benda dan keberuntungan yang besar dalam kehidupan. Padahal semua itu akan binasa bila tidak beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3331",
      ),
      Ayah(
        numberInSurah: 80,
        numberInQuran: 3332,
        juz: 20,
        page: 395,
        arab: "\u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064f\u0648\u062a\u064f\u0648\u0627 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u064e \u0648\u064e\u064a\u0652\u0644\u064e\u0643\u064f\u0645\u0652 \u062b\u064e\u0648\u064e\u0627\u0628\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u062e\u064e\u064a\u0652\u0631\u064c \u0644\u0651\u0650\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064e \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627 \u0648\u064e\u0644\u064e\u0627 \u064a\u064f\u0644\u064e\u0642\u0651\u064e\u0627\u0647\u064e\u0627 \u0625\u0650\u0644\u0651\u064e\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa qaalal lazeena ootul 'ilma wailakum sawaabul laahi khairul liman aamana wa 'amila saalihaa; wa laa yulaq qaahaaa illas saabiroon",
        translation: "Tetapi orang-orang yang dianugerahi ilmu berkata, \u201cCelakalah kamu! Ketahuilah, pahala Allah lebih baik bagi orang-orang yang beriman dan mengerjakan kebajikan, dan (pahala yang besar) itu hanya diperoleh oleh orang-orang yang sabar.\u201d",
        shortTafsir: "Akan tetapi, orang-orang yang dianugerahi ilmu oleh Allah dalam bentuk ilmu yang bermanfaat tidak tertipu oleh itu semua. Mereka memberi nasihat kepada orang-orang yang tertipu itu dengan berkata, \u201cCelakalah kamu jika bersikap dan berkeyakinan seperti itu! Bertakwalah kepada Allah dan taatlah kepada-Nya. Ketahuilah, pahala dan kenikmatan yang disediakan oleh Allah di sisi-Nya lebih baik bagi orang-orang yang beriman dan mengerjakan kebajikan dari pada kekayaan yang dimiliki dan dipamerkan oleh Karun, dan pahala yang besar itu hanya diperoleh oleh orang-orang yang sabar dan tabah dalam melaksanakan konsekuensi keimanan dan amal saleh serta menerima ujian dan cobaan dari Allah.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3332",
      ),
      Ayah(
        numberInSurah: 81,
        numberInQuran: 3333,
        juz: 20,
        page: 395,
        arab: "\u0641\u064e\u062e\u064e\u0633\u064e\u0641\u0652\u0646\u064e\u0627 \u0628\u0650\u0647\u0650 \u0648\u064e\u0628\u0650\u062f\u064e\u0627\u0631\u0650\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u064e \u0641\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0645\u0650\u0646 \u0641\u0650\u0626\u064e\u0629\u064d \u064a\u064e\u0646\u0635\u064f\u0631\u064f\u0648\u0646\u064e\u0647\u064f \u0645\u0650\u0646 \u062f\u064f\u0648\u0646\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0646\u062a\u064e\u0635\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Fakhasafnaa bihee wa bidaarihil arda famaa kaana laho min fi'atiny yansuroo nahoo min doonil laahi wa maa kaana minal muntasireen",
        translation: "Maka Kami benamkan dia (Karun) bersama rumahnya ke dalam bumi. Maka tidak ada baginya satu golongan pun yang akan menolongnya selain Allah, dan dia tidak termasuk orang-orang yang dapat membela diri.",
        shortTafsir: "Sebagai akibat dari sikapnya yang sombong dan keras kepala dalam kedurhakaan, meski telah dinasihati, maka sangat wajar bila Kami benamkan dia dengan cara melongsorkan tanah sehingga ia terbenam bersama rumah, harta benda dan seluruh perhiasan-nya ke dalam perut bumi. Maka tidak ada baginya satu golongan pun, baik keluarga maupun lainnya, yang akan menolongnya dari azab tersebut selain Allah, dan dia tidak termasuk orang-orang yang dapat membela diri ketika datang azab Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3333",
      ),
      Ayah(
        numberInSurah: 82,
        numberInQuran: 3334,
        juz: 20,
        page: 395,
        arab: "\u0648\u064e\u0623\u064e\u0635\u0652\u0628\u064e\u062d\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u062a\u064e\u0645\u064e\u0646\u0651\u064e\u0648\u0652\u0627 \u0645\u064e\u0643\u064e\u0627\u0646\u064e\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0633\u0650 \u064a\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0646\u064e \u0648\u064e\u064a\u0652\u0643\u064e\u0623\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u064a\u064e\u0628\u0652\u0633\u064f\u0637\u064f \u0627\u0644\u0631\u0651\u0650\u0632\u0652\u0642\u064e \u0644\u0650\u0645\u064e\u0646 \u064a\u064e\u0634\u064e\u0627\u0621\u064f \u0645\u0650\u0646\u0652 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u0647\u0650 \u0648\u064e\u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u06d6 \u0644\u064e\u0648\u0652\u0644\u064e\u0627 \u0623\u064e\u0646 \u0645\u0651\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0644\u064e\u062e\u064e\u0633\u064e\u0641\u064e \u0628\u0650\u0646\u064e\u0627 \u06d6 \u0648\u064e\u064a\u0652\u0643\u064e\u0623\u064e\u0646\u0651\u064e\u0647\u064f \u0644\u064e\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062d\u064f \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u064f\u0648\u0646\u064e",
        transliteration: "Wa asbahal lazeena tamannaw makaanahoo bil amsi yaqooloona waika annal laaha yabsutur rizqa limany ya shaaa'u min 'ibaadihee wa yaqdiru law laaa am mannal laahu 'alainaa lakhasafa binaa waika annahoo laa yuflihul kaafiroon",
        translation: "Dan orang-orang yang kemarin mengangan-angankan kedudukannya (Karun) itu berkata, \u201cAduhai, benarlah kiranya Allah yang melapangkan rezeki bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya dan membatasi (bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya). Sekiranya Allah tidak melimpahkan karunia-Nya pada kita, tentu Dia telah membenamkan kita pula. Aduhai, benarlah kiranya tidak akan beruntung orang-orang yang mengingkari (nikmat Allah).\u201d",
        shortTafsir: "Dan orang-orang yang kemarin mengangan-angankan dengan penuh harapan untuk mendapatkan kedudukan seperti kedudukan yang diraihnya itu mengulang-ulang kata-kata penyesalan setelah mereka merenungi apa yang menimpa Karun. Mereka berkata, \u201cAduhai, benarlah kiranya Allah yang melapangkan rezeki bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya, baik yang mukmin maupun yang kafir, pandai atau tidak, mulia atau hina. Dan sebaliknya, Allah membatasi dan menyempitkan rezeki bagi siapa yang Dia kehendaki di antara hamba-hamba-Nya. Sekiranya Allah tidak melimpahkan karunia-Nya pada kita, berupa petunjuk kepada keimanan dan menjaga kita dari keterjerumusan dalam kesesatan dan kesombongan, tentu Dia telah membenamkan kita pula sebagaimana dialami oleh Karun. Aduhai, benarlah kiranya tidak akan beruntung orang-orang yang mengingkari nikmat Allah, baik di dunia maupun di akhirat kelak.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3334",
      ),
      Ayah(
        numberInSurah: 83,
        numberInQuran: 3335,
        juz: 20,
        page: 395,
        arab: "\u062a\u0650\u0644\u0652\u0643\u064e \u0627\u0644\u062f\u0651\u064e\u0627\u0631\u064f \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u064f \u0646\u064e\u062c\u0652\u0639\u064e\u0644\u064f\u0647\u064e\u0627 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u062f\u064f\u0648\u0646\u064e \u0639\u064f\u0644\u064f\u0648\u0651\u064b\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0648\u064e\u0644\u064e\u0627 \u0641\u064e\u0633\u064e\u0627\u062f\u064b\u0627 \u06da \u0648\u064e\u0627\u0644\u0652\u0639\u064e\u0627\u0642\u0650\u0628\u064e\u0629\u064f \u0644\u0650\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e",
        transliteration: "Tilkad Daarul Aakhiratu naj'aluhaa lillazeena laa yureedoona 'uluwwan fil ardi wa laa fasaadaa; wal 'aaqibatu lilmuttaqeen",
        translation: "Negeri akhirat itu Kami jadikan bagi orang-orang yang tidak menyombongkan diri dan tidak berbuat kerusakan di bumi. Dan kesudahan (yang baik) itu bagi orang-orang yang bertakwa.",
        shortTafsir: "Begitulah akhir kisah Karun yang binasa karena keangkuhannya. Kebahagiaan yang hakiki, yaitu di akhirat kelak, tidak akan diperoleh oleh orang seperti Karun. Kenikmatan negeri akhirat itu Kami jadikan bagi orang-orang yang tidak menyombongkan diri dengan kekuasaan yang dimilikinya dan tidak berbuat kerusakan di bumi dengan melakukan kemaksiatan dan kejahatan. Dan kesudahan yang baik itu, yaitu surga, hanya bagi orang-orang yang bertakwa, yaitu orang-orang yang kalbunya penuh dengan keimanan karena rasa takut kepada Allah, sehingga mereka melakukan apa yang diridai Allah.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3335",
      ),
      Ayah(
        numberInSurah: 84,
        numberInQuran: 3336,
        juz: 20,
        page: 395,
        arab: "\u0645\u064e\u0646 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0647\u064f \u062e\u064e\u064a\u0652\u0631\u064c \u0645\u0651\u0650\u0646\u0652\u0647\u064e\u0627 \u06d6 \u0648\u064e\u0645\u064e\u0646 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0629\u0650 \u0641\u064e\u0644\u064e\u0627 \u064a\u064f\u062c\u0652\u0632\u064e\u0649 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0633\u0651\u064e\u064a\u0651\u0650\u0626\u064e\u0627\u062a\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e",
        transliteration: "Man jaaa'a bilhasanati falahoo khairum minhaa wa man jaaa'a bissaiyi'ati falaa yujzal lazeena 'amilus saiyiaati illaa maa kaanoo ya'maloon",
        translation: "Barangsiapa datang dengan (membawa) kebaikan, maka dia akan mendapat (pahala) yang lebih baik daripada kebaikannya itu; dan barang siapa datang dengan (membawa) kejahatan, maka orang-orang yang telah mengerjakan kejahatan itu hanya diberi balasan (seimbang) dengan apa yang dahulu mereka kerjakan.",
        shortTafsir: "Barangsiapa datang pada Hari Kiamat dengan membawa amal kebaikan yang penuh ketulusan dan sesuai tuntunan yang diajarkan oleh Allah dan Rasul-Nya, maka dia akan mendapat pahala berlipat ganda, mulai dari sepuluh hingga tujuh ratus kali, bahkan tidak terbatas, yang lebih baik daripada kebaikannya itu; dan barang siapa datang dengan membawa amal kejahatan dalam bentuk kekufuran dan kemaksiatan, maka orang-orang yang telah mengerjakan kejahatan itu hanya diberi balasan seimbang dengan apa yang dahulu selalu mereka kerjakan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3336",
      ),
      Ayah(
        numberInSurah: 85,
        numberInQuran: 3337,
        juz: 20,
        page: 396,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u0641\u064e\u0631\u064e\u0636\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064e \u0644\u064e\u0631\u064e\u0627\u062f\u0651\u064f\u0643\u064e \u0625\u0650\u0644\u064e\u0649\u0670 \u0645\u064e\u0639\u064e\u0627\u062f\u064d \u06da \u0642\u064f\u0644 \u0631\u0651\u064e\u0628\u0651\u0650\u064a \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0645\u064e\u0646 \u062c\u064e\u0627\u0621\u064e \u0628\u0650\u0627\u0644\u0652\u0647\u064f\u062f\u064e\u0649\u0670 \u0648\u064e\u0645\u064e\u0646\u0652 \u0647\u064f\u0648\u064e \u0641\u0650\u064a \u0636\u064e\u0644\u064e\u0627\u0644\u064d \u0645\u0651\u064f\u0628\u0650\u064a\u0646\u064d",
        transliteration: "Innal azee farada 'alaikal Qur-aana laraaadduka ilaa ma'aad; qur Rabbeee a'lamu man jjaaa'a bil hudaa wa man huwa fee dalaalim mubeen",
        translation: "Sesungguhnya (Allah) yang mewajibkan engkau (Muhammad) untuk (melaksanakan hukum-hukum) Al-Qur'an, benar-benar akan mengembalikanmu ke tempat kembali. Katakanlah (Muhammad), \u201cTuhanku mengetahui orang yang membawa petunjuk dan orang yang berada dalam kesesatan yang nyata.\u201d",
        shortTafsir: "Negeri akhirat merupakan negeri tempat kembali semua makhluk, dan semua semua akan menuju ke sana dan menerima balasan dan ganjaran, termasuk Nabi Muhammad. Sesungguhnya Allah yang menurunkan Al-Qur'an dan mewajibkan engkau wahai Nabi Muhammad untuk menyampaikan pesan-pesan Al-Qur'an dan berpegang teguh kepadanya, benar-benar akan mengembalikanmu ke tempat kembali, yaitu kota Mekah, atau akhirat kelak. Inilah suatu janji dari Tuhan bahwa Nabi Muhammad akan kembali ke Mekah sebagai orang yang menang, dan ini sudah terjadi pada tahun kedelapan Hijriah, pada waktu Nabi menaklukkan Mekah. Ini merupakan suatu mukjizat bagi Nabi Muhammad. Katakanlah wahai Nabi Muhammad, kepada orang-orang musyrik, \u201cTuhanku mengetahui dengan ilmu yang tiada bandingannya tentang orang yang datang membawa petunjuk dan orang yang berada dalam kesesatan yang nyata yang diketahui oleh setiap orang berakal yang memiliki pengetahuan yang benar.\u201d",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3337",
      ),
      Ayah(
        numberInSurah: 86,
        numberInQuran: 3338,
        juz: 20,
        page: 396,
        arab: "\u0648\u064e\u0645\u064e\u0627 \u0643\u064f\u0646\u062a\u064e \u062a\u064e\u0631\u0652\u062c\u064f\u0648 \u0623\u064e\u0646 \u064a\u064f\u0644\u0652\u0642\u064e\u0649\u0670 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0625\u0650\u0644\u0651\u064e\u0627 \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0645\u0651\u0650\u0646 \u0631\u0651\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0638\u064e\u0647\u0650\u064a\u0631\u064b\u0627 \u0644\u0651\u0650\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e",
        transliteration: "Wa maa kunta tarjooo ai yulqaaa ilaikal Kitaabu illaa rahmatam mir Rabbika falaa takoonanna zaheeral lilkaafireen",
        translation: "Dan engkau (Muhammad) tidak pernah mengharap agar Kitab (Al-Qur'an) itu diturunkan kepadamu, tetapi ia (diturunkan) sebagai rahmat dari Tuhanmu, sebab itu janganlah sekali-kali engkau menjadi penolong bagi orang-orang kafir,",
        shortTafsir: "Pada masa sebelum turunnya wahyu pertama, engkau wahai Nabi Muhammad tidak pernah menduga dan mengharap agar Kitab Al-Qur'an itu diturunkan kepadamu, tetapi ternyata ia diturunkan oleh Allah kepadamu. Hal ini adalah sebagai rahmat yang sangat besar dari Tuhanmu, bagi dirimu dan seluruh makhluk di alam raya ini. Oleh sebab itu, ingatlah nikmat tersebut, dan tetaplah menyampaikannya. Janganlah sekali-kali engkau menjadi penolong bagi orang-orang kafir.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3338",
      ),
      Ayah(
        numberInSurah: 87,
        numberInQuran: 3339,
        juz: 20,
        page: 396,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0635\u064f\u062f\u0651\u064f\u0646\u0651\u064e\u0643\u064e \u0639\u064e\u0646\u0652 \u0622\u064a\u064e\u0627\u062a\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0628\u064e\u0639\u0652\u062f\u064e \u0625\u0650\u0630\u0652 \u0623\u064f\u0646\u0632\u0650\u0644\u064e\u062a\u0652 \u0625\u0650\u0644\u064e\u064a\u0652\u0643\u064e \u06d6 \u0648\u064e\u0627\u062f\u0652\u0639\u064f \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u06d6 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0643\u064f\u0648\u0646\u064e\u0646\u0651\u064e \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0645\u064f\u0634\u0652\u0631\u0650\u0643\u0650\u064a\u0646\u064e",
        transliteration: "Wa laa yasuddunnaka 'an Aayaatil laahi ba'da iz unzilat ilaika wad'u ilaa Rabbika wa laa takonanna minal mushrikeen",
        translation: "dan jangan sampai mereka menghalang-halangi engkau (Muhammad) untuk (menyampaikan) ayat-ayat Allah, setelah ayat-ayat itu diturunkan kepadamu, dan serulah (manusia) agar (beriman) kepada Tuhanmu, dan janganlah engkau termasuk orang-orang musyrik.",
        shortTafsir: "Dan jangan sampai mereka menghalang-halangi engkau wahai Nabi Muhammad untuk menyampaikan ayat-ayat Allah, setelah ayat-ayat itu diturunkan oleh Allah kepadamu, dan serulah manusia dengan sekuat kemampuanmu melalui dakwah yang santun dan bijak kepada agama Allah agar mereka beriman kepada Tuhanmu, jangan bosan berdakwah kendati mereka enggan mendengar atau menghalang-halangi, dan sekali-kali dalam keadaan apa pun janganlah engkau diam tidak menegur kedurhakaan yang mengandung kemusyrikan, apalagi merestuinya, karena jika demikian engkau termasuk orang-orang musyrik yang mempersekutukan Tuhan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3339",
      ),
      Ayah(
        numberInSurah: 88,
        numberInQuran: 3340,
        juz: 20,
        page: 396,
        arab: "\u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u0652\u0639\u064f \u0645\u064e\u0639\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0625\u0650\u0644\u064e\u0670\u0647\u064b\u0627 \u0622\u062e\u064e\u0631\u064e \u06d8 \u0644\u064e\u0627 \u0625\u0650\u0644\u064e\u0670\u0647\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0647\u064f\u0648\u064e \u06da \u0643\u064f\u0644\u0651\u064f \u0634\u064e\u064a\u0652\u0621\u064d \u0647\u064e\u0627\u0644\u0650\u0643\u064c \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u062c\u0652\u0647\u064e\u0647\u064f \u06da \u0644\u064e\u0647\u064f \u0627\u0644\u0652\u062d\u064f\u0643\u0652\u0645\u064f \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u062a\u064f\u0631\u0652\u062c\u064e\u0639\u064f\u0648\u0646\u064e",
        transliteration: "Wa laa tad'u ma'al laahi ilaahan aakhar; laaa ilaaha illaa Hoo; kullu shai'in haalikun illaa Wajhah; lahul hukkmu wa ilaihi turja'oon",
        translation: "Dan jangan (pula) engkau sembah tuhan yang lain selain Allah. Tidak ada tuhan (yang berhak disembah) selain Dia. Segala sesuatu pasti binasa, kecuali Allah. Segala keputusan menjadi wewenang-Nya, dan hanya kepada-Nya kamu dikembalikan.",
        shortTafsir: "Dan jangan pula engkau sembah tuhan yang lain selain Allah. Tidak ada tuhan pengendali dan penguasa seluruh alam yang berhak disembah selain Dia Yang Maha Esa lagi Mahakekal itu. Segala sesuatu pasti binasa dan fana, kecuali Allah. Segala keputusan di dunia dan akhirat menjadi wewenang-Nya, dan hanya kepada-Nya kamu dan seluruh makhluk dikembalikan.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/3340",
      ),
    ],
  );
